class TestRunIngestion:
    @pytest.mark.asyncio
    async def test_ingestion_processes_all_commits(self, real_db, git_repo, monkeypatch):
        import mcp_server
        mcp_server._ingest_progress = {
            "status": "idle", "total": 0,
            "current_commit": "", "error": None,
        }
        await mcp_server._run_ingestion(str(git_repo), "HEAD")
        assert mcp_server._ingest_progress["status"] == "complete"
        assert _walk_claimed() == 2

    @pytest.mark.asyncio
    async def test_sets_error_at_timestamp_on_failure(self, real_db, git_repo, monkeypatch):
        import mcp_server
        mcp_server._ingest_progress = {
            "status": "idle", "total": 0, "prior_ingested": 0,
            "current_commit": "", "error": None, "owner_pid": None, "error_at": None,
        }

        def raise_error(repo_path, watermark, branch):
            raise RuntimeError("boom")

        monkeypatch.setattr(mcp_server, "_git_commits", raise_error)
        await mcp_server._run_ingestion(str(git_repo), "HEAD")
        assert mcp_server._ingest_progress["status"] == "error"
        assert "boom" in mcp_server._ingest_progress["error"]
        assert mcp_server._ingest_progress["error_at"] is not None
        assert mcp_server._ingest_progress["error_at"].endswith("Z")

    @pytest.mark.asyncio
    async def test_prints_the_swallowed_failure_to_stderr(
        self, real_db, git_repo, monkeypatch, capsys,
    ):
        """#270. _run_ingestion catches its own exception and returns
        normally, so without this print the text existed ONLY in
        _ingest_progress["error"] -- a dict that lives in the server
        process. A background run started through
        handle_minigraf_ingest_git left nothing in any log, and the at-scale
        harness could not scan for what was never written to fd 2. That is
        what made #270 unattributable for 48 sampled runs.

        The TRACEBACK, not just str(e): the message alone is frequently
        useless for locating the failure (str() of a bare KeyError is the
        key and nothing else), and this handler covers ~500 lines of
        _run_ingestion.
        """
        import mcp_server
        mcp_server._ingest_progress = {
            "status": "idle", "total": 0, "prior_ingested": 0,
            "current_commit": "", "error": None, "owner_pid": None, "error_at": None,
        }

        def raise_error(repo_path, watermark, branch):
            raise RuntimeError("boom from _git_commits")

        monkeypatch.setattr(mcp_server, "_git_commits", raise_error)
        await mcp_server._run_ingestion(str(git_repo), "HEAD")

        err = capsys.readouterr().err
        assert "[_run_ingestion] ingestion failed: boom from _git_commits" in err
        assert "Traceback (most recent call last)" in err
        # The raising line itself -- proof the traceback is the real one and
        # not a formatted stand-in built from str(e).
        assert 'raise RuntimeError("boom from _git_commits")' in err
        # Unchanged: printing must not stop the handler recording the run.
        assert mcp_server._ingest_progress["status"] == "error"

    @pytest.mark.asyncio
    async def test_watermark_updated_after_each_commit(self, real_db, git_repo, monkeypatch):
        import mcp_server
        # #222 phase 2d: :ingestion/watermark keeps its "contiguous from C0"
        # meaning and is advanced by the FORWARD stream only -- the reverse
        # stream never touches it. Pin the ratio forward-only so the forward
        # stream claims both of git_repo's commits, which is what makes
        # "one watermark write per commit" the property under test rather
        # than a statement about the 1:1 split.
        monkeypatch.setenv("MINIGRAF_INGEST_STREAM_RATIO", f"{10**6}:1")
        mcp_server._ingest_progress = {
            "status": "idle", "total": 0,
            "current_commit": "", "error": None,
        }
        with execute_spy() as calls:
            await mcp_server._run_ingestion(str(git_repo), "HEAD")
        watermark_calls = [
            c for c in calls if ":ingestion/watermark" in c and "transact" in c
        ]
        assert len(watermark_calls) >= 2  # one per commit

    @pytest.mark.asyncio
    async def test_per_commit_get_db_lock_retry_does_not_block_event_loop(
        self, real_db, git_repo, monkeypatch
    ):
        """Regression test for #99: a lock-retry hit while reacquiring the DB
        between commits must not block via time.sleep() — _run_ingestion runs
        on the single-threaded event loop, and a blocking sleep there would
        freeze the very coroutine responsible for eventually releasing that
        lock.

        Real-backend version: rather than a canned MagicMock.open.side_effect
        list, this wraps the real (in-memory-backed) MiniGrafDb.open that
        real_db already installed — same technique as
        TestGetDbLockRetry.test_retries_open_after_clearing_stale_lock_on_final_attempt
        — so a per-commit reacquire raises a genuine MiniGrafError('...locked...')
        once, then every subsequent call opens a real handle normally.

        Under the lease protocol the target call count shifted from 1 to 3:
        real_db's own lease must be released first (below) or every
        acquisition inside _run_ingestion would just REUSE its still-open
        handle -- count > 0 never calls MiniGrafDb.open() at all, so
        flaky_open would never fire. Released, the preload (call 1) and the
        stamp/frontier_load phase (call 2) each now do a genuine fresh open
        of their own -- neither is what this test is about -- so the first
        per-commit reacquire is the 3rd real open, not the 1st.
        """
        import mcp_server
        from minigraf import MiniGrafDb

        # See docstring: must be released so _run_ingestion's own
        # acquisitions are genuine opens rather than reusing this handle.
        mcp_server._reset_db_state()

        base_open = MiniGrafDb.open
        call_count = {"n": 0}
        FAIL_ON_CALL = 3  # first per-commit reacquire -- see docstring

        def flaky_open(path):
            call_count["n"] += 1
            if call_count["n"] == FAIL_ON_CALL:
                raise MiniGrafError(
                    "Database is locked by another process (lock file: x.graph.lock, holder PID: 1)."
                )
            return base_open(path)

        monkeypatch.setattr(MiniGrafDb, "open", staticmethod(flaky_open))
        mcp_server._ingest_progress = {
            "status": "idle", "total": 0,
            "current_commit": "", "error": None,
        }

        _forbid_blocking_sleep_on_event_loop(monkeypatch)

        await mcp_server._run_ingestion(str(git_repo), "HEAD")

        assert mcp_server._ingest_progress["status"] == "complete"
        assert _walk_claimed() == 2
        assert call_count["n"] >= 2, "expected the flaky open() to actually be exercised"

    @pytest.mark.asyncio
    async def test_preload_phase_does_not_block_event_loop(
        self, real_db, git_repo, monkeypatch
    ):
        """Regression test for #103: opening the DB and running the startup
        preload queries (_watermark_query, _count_commit_entities,
        _preload_known_entities/_deps/_pinned_commits) must run off the event
        loop. Before the fix these ran synchronously inline with no `await`
        between them, so on a large graph the phase could run long enough to
        starve the stdio handshake past a client's connection timeout,
        leaving the server permanently unable to connect."""
        import mcp_server

        def slow_preload(db, repo_path, valid_at=None, hash_to_pos=None,
                         watermark_pos=None, ts_positions=None, t_hi_ms=None,
                         stats=None):
            time.sleep(0.3)
            return {}, {}, {}, {}, {}

        monkeypatch.setattr(mcp_server, "_preload_known_entities", slow_preload)
        mcp_server._ingest_progress = {
            "status": "idle", "total": 0,
            "current_commit": "", "error": None,
        }

        heartbeat_ticks = 0

        async def heartbeat():
            nonlocal heartbeat_ticks
            while True:
                heartbeat_ticks += 1
                await asyncio.sleep(0.02)

        heartbeat_task = asyncio.create_task(heartbeat())
        await mcp_server._run_ingestion(str(git_repo), "HEAD")
        heartbeat_task.cancel()
        with contextlib.suppress(asyncio.CancelledError):
            await heartbeat_task

        assert heartbeat_ticks >= 5, (
            "event loop was starved during the preload phase: only "
            f"{heartbeat_ticks} heartbeat ticks during a 0.3s slow preload"
        )

    @pytest.mark.asyncio
    async def test_db_released_between_commits(self, real_db, git_repo, monkeypatch):
        import mcp_server
        mcp_server._ingest_progress = {
            "status": "idle", "total": 0,
            "current_commit": "", "error": None,
        }
        # real_db holds its own lease for the test's duration (the shim's,
        # released by _reset_db_state()) -- a separate, legitimate holder.
        # What this proves is that _run_ingestion released ITS OWN lease at
        # every yield point, i.e. the count returns to this baseline, not
        # that no lease exists anywhere (which real_db's presence would
        # falsify trivially).
        baseline = mcp_server._lease_manager.lease_count
        db_none_snapshots = []

        original_sleep = asyncio.sleep
        async def patched_sleep(t):
            # Stage B (phase == "sweeping") deliberately holds ONE lease
            # across its whole batch rather than releasing between its own
            # internal commits -- confirmed unchanged from the pre-#255 code
            # (it held the old `_db` global the same way). This test's name
            # and intent are about Stage A's per-commit release cadence, so
            # only snapshot outside Stage B.
            if mcp_server._ingest_progress.get("phase") != "sweeping":
                db_none_snapshots.append(mcp_server._lease_manager.lease_count == baseline)
            await original_sleep(t)

        with patch("mcp_server.asyncio.sleep", patched_sleep):
            await mcp_server._run_ingestion(str(git_repo), "HEAD")

        assert db_none_snapshots, "expected at least one per-commit yield to check"
        assert all(db_none_snapshots), f"_db was not None at yield: {db_none_snapshots}"

    @pytest.mark.asyncio
    async def test_local_db_reference_dropped_before_repo_total_enumeration(
        self, git_repo, monkeypatch
    ):
        """Regression test for #84's deeper root cause: minigraf exposes no
        explicit close(), so the OS-level file lock is only released once
        *every* reference to the handle is gone via CPython refcounting.
        Clearing the module-global `_db` alone is not enough if
        `_run_ingestion`'s local `db` variable still points at the same
        object — verified against the real (unmocked) minigraf FFI, where a
        stale local reference left the `.lock` file in place.

        #238 moved `_git_commits`' FULL-history walk (and
        `build_linearization`) to ABOVE the DB open entirely, so that
        enumeration no longer has a stale-reference window to guard at all —
        no DB handle exists yet when it runs (see
        test_git_commits_runs_before_any_db_is_opened below, which pins
        exactly that). The next potentially slow git subprocess after the
        preload releases the lock is now the `git rev-list --count HEAD`
        total-count call just below `_db = None`, so this test retargets
        there: that call has no `await` before it either, so a stale local
        `db` reference in `_run_ingestion`'s frame would hold the lock for
        its entire duration same as before.

        No real_db fixture here — this test's whole point
        is CPython refcounting on the DB handle object itself, so it needs a
        deliberately lightweight, non-mock handle. real_db's actual FFI
        object carries its own internal cross-references that would pollute
        sys.getrefcount() just as badly as MagicMock's self-referential
        state does (see _FakeDb's docstring below), so MiniGrafDb.open is
        monkeypatched directly to a plain-object factory instead.
        """
        import mcp_server
        from minigraf import MiniGrafDb

        class _FakeDb:
            """Plain object, not MagicMock — MagicMock carries internal
            self-referential state that inflates sys.getrefcount() far past
            what a real released reference would show."""
            def execute(self, *a, **k):
                return json.dumps({"results": []})
            def checkpoint(self):
                pass

        opened_instances = []

        def _open(path):
            inst = _FakeDb()
            opened_instances.append(inst)
            return inst

        monkeypatch.setattr(MiniGrafDb, "open", staticmethod(_open))
        mcp_server._reset_db_state()
        mcp_server._ingest_progress = {
            "status": "idle", "total": 0,
            "current_commit": "", "error": None,
        }

        refcount_at_enumeration = {}
        real_run = mcp_server._subprocess.run

        def spy_run(cmd, *args, **kwargs):
            if cmd[:2] == ["git", "rev-list"]:
                assert len(opened_instances) == 1
                refcount_at_enumeration["count"] = sys.getrefcount(opened_instances[0])
            return real_run(cmd, *args, **kwargs)

        with patch.object(mcp_server._subprocess, "run", side_effect=spy_run):
            await mcp_server._run_ingestion(str(git_repo), "HEAD")

        # 1 ref for opened_instances' slot + 1 for the local `inst` in
        # sys.getrefcount's own argument frame == 2 if nothing else (e.g. a
        # stale `db` local in _run_ingestion's frame) is still holding it.
        assert refcount_at_enumeration["count"] <= 2, (
            "a stale local reference kept the DB instance (and its file "
            f"lock) alive during the repo-total enumeration: "
            f"refcount={refcount_at_enumeration['count']}"
        )

    @pytest.mark.asyncio
    async def test_git_commits_runs_before_any_db_is_opened(
        self, git_repo, monkeypatch
    ):
        """#238: `_git_commits` (and `build_linearization`) must run ABOVE
        the DB open, not merely above the `_db = None` lock-release, so the
        graph file lock is never held during the full-history walk at all --
        see _run_ingestion's comment above `build_linearization`. Pins the
        ordering directly: no DB has been opened yet at the moment
        `_git_commits` is called.
        """
        import mcp_server
        from minigraf import MiniGrafDb

        class _FakeDb:
            def execute(self, *a, **k):
                return json.dumps({"results": []})
            def checkpoint(self):
                pass

        opened_instances = []

        def _open(path):
            inst = _FakeDb()
            opened_instances.append(inst)
            return inst

        monkeypatch.setattr(MiniGrafDb, "open", staticmethod(_open))
        mcp_server._reset_db_state()
        mcp_server._ingest_progress = {
            "status": "idle", "total": 0,
            "current_commit": "", "error": None,
        }

        opened_count_at_enumeration = {}
        real_git_commits = mcp_server._git_commits

        def spy_git_commits(repo, watermark, branch):
            opened_count_at_enumeration["count"] = len(opened_instances)
            return real_git_commits(repo, watermark, branch)

        with patch.object(mcp_server, "_git_commits", side_effect=spy_git_commits):
            await mcp_server._run_ingestion(str(git_repo), "HEAD")

        assert opened_count_at_enumeration["count"] == 0, (
            "a DB was already open when _git_commits ran -- the full-history "
            "enumeration must precede the DB open entirely (#238)"
        )

