            assert results(f"(query [:find ?x :where [{new_ident} :ident ?x]])") == [[new_ident]], \
                "New global must be open after rename"
            assert results(f"(query [:find ?x :where [{new_ident} :renamed-from ?x]])") == [[old_ident]]
