class TestFieldClassContainmentE2E:
    """Real-backend (non-mocked) end-to-end test: a class field is queryable via
    the class's :contains edge in the live graph, and that edge is closed when
    the field is removed (issues.md P2: "add a graph-level test asserting a
    class's :contains set includes its fields" + close-logic verification)."""

    def _init_repo(self, repo):
        _subprocess.run(["git", "init"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.email", "t@t.com"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.name", "T"], cwd=repo, check=True, capture_output=True)

    def _commit(self, repo, msg):
        _subprocess.run(["git", "add", "."], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "commit", "-m", msg], cwd=repo, check=True, capture_output=True)

    def _query(self, path, q):
        from minigraf import MiniGrafDb
        db = MiniGrafDb.open(path)
        try:
            return json.loads(db.execute(q)).get("results", [])
        finally:
            del db

    def test_class_contains_field_is_queryable_and_closed_on_removal(self, tmp_path, monkeypatch):
        import mcp_server
        repo = tmp_path / "repo"
        repo.mkdir()
        self._init_repo(repo)

        # Commit 1: a class with a field.
        (repo / "models.py").write_text("class Account:\n    balance = 0\n")
        self._commit(repo, "add Account")

        graph_path = str(tmp_path / "e2e.graph")
        monkeypatch.setenv("MINIGRAF_GRAPH_PATH", graph_path)
        mcp_server._reset_db_state()

        asyncio.run(mcp_server._run_ingestion(str(repo), "HEAD"))
        mcp_server._reset_db_state()

        class_ident = mcp_server._code_ident("class", "models.py", "Account")
        field_ident = mcp_server._code_ident("field", "models.py", "Account.balance")

        # The class :contains set includes its field (structural graph traversal).
        contains = self._query(
            graph_path, f"(query [:find ?f :where [{class_ident} :contains ?f]])"
        )
        contained = {row[0] for row in contains}
        assert field_ident in contained, f"expected {field_ident} in class :contains {contained}"

        # Commit 2: remove the field (replace with a method) so it is a removal.
        (repo / "models.py").write_text("class Account:\n    def deposit(self):\n        pass\n")
        self._commit(repo, "drop balance field")

        mcp_server._reset_db_state()
        asyncio.run(mcp_server._run_ingestion(str(repo), "HEAD"))
        mcp_server._reset_db_state()

        # The class-contains edge to the removed field is CLOSED at current time.
        contains_after = self._query(
            graph_path, f"(query [:find ?f :where [{class_ident} :contains ?f]])"
        )
        contained_after = {row[0] for row in contains_after}
        assert field_ident not in contained_after, (
            f"class-contains edge to removed field leaked open: {contained_after}"
        )

        # And the module-contains edge to the field is closed too (no half-close).
        module_ident = mcp_server._code_ident("module", "models.py")
        mod_contains_after = {
            row[0] for row in self._query(
                graph_path, f"(query [:find ?f :where [{module_ident} :contains ?f]])"
            )
        }
        assert field_ident not in mod_contains_after


class TestReverseFillClaimAndProcess:
    def _repo_with_evolving_function(self, tmp_path):
        """Three commits, each genuinely changing auth.py's login() body (not
        just whitespace -- #221's unchanged-body detection would otherwise
        suppress :modified-in and complicate the assertions below), plus an
        unrelated function added at h1/h2 so the file is in each commit's
        diff for a real reason."""
        repo = tmp_path / "repo"
        repo.mkdir()
        _subprocess.run(["git", "init"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.email", "t@t.com"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.name", "T"], cwd=repo, check=True, capture_output=True)

        (repo / "auth.py").write_text("def login():\n    return 1\n")
        _subprocess.run(["git", "add", "."], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "commit", "-m", "h0"], cwd=repo, check=True, capture_output=True)

        (repo / "auth.py").write_text("def login():\n    return 2\n\ndef extra():\n    pass\n")
        _subprocess.run(["git", "add", "."], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "commit", "-m", "h1"], cwd=repo, check=True, capture_output=True)

        (repo / "auth.py").write_text(
            "def login():\n    return 3\n\ndef extra():\n    pass\n\ndef more():\n    pass\n"
        )
        _subprocess.run(["git", "add", "."], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "commit", "-m", "h2"], cwd=repo, check=True, capture_output=True)
        return repo

    def _allocator_and_metadata(self, repo, real_db):
        import mcp_server
        import frontier_registry
        linearization = frontier_registry.build_linearization(str(repo))
        commit_metadata = mcp_server._git_commits(str(repo), watermark_hash=None)
        allocator = mcp_server._frontier_load(real_db, linearization, "2026-01-04T00:00:00Z")
        return linearization, commit_metadata, allocator

    def test_gap_empty_returns_none_and_writes_nothing(self, real_db, tmp_path):
        import mcp_server
        repo = self._repo_with_evolving_function(tmp_path)
        linearization, commit_metadata, allocator = self._allocator_and_metadata(repo, real_db)
        # Drain the gap entirely first (forward-claim everything low).
        while allocator.claim_low() is not None:
            pass

        result = mcp_server._reverse_fill_claim_and_process(
            real_db, str(repo), linearization, commit_metadata, allocator,
        )
        assert result is None

    def test_single_claim_writes_structure_and_provisional_introduced_by(self, real_db, tmp_path):
        import mcp_server
        repo = self._repo_with_evolving_function(tmp_path)
        linearization, commit_metadata, allocator = self._allocator_and_metadata(repo, real_db)

        claimed_hash = mcp_server._reverse_fill_claim_and_process(
            real_db, str(repo), linearization, commit_metadata, allocator,
        )
        assert claimed_hash == linearization[-1]  # newest commit (h2) claimed first

        fn_ident = mcp_server._code_ident("function", "auth.py", "login")
        commit_ident = f":commit/{claimed_hash[:12]}"
        assert mcp_server._entity_introduced_by_query(real_db, fn_ident) == commit_ident
        assert mcp_server._lineage_is_provisional(real_db, fn_ident) is True

    def test_walking_backward_moves_introduced_by_to_the_oldest_commit(self, real_db, tmp_path):
        import mcp_server
        repo = self._repo_with_evolving_function(tmp_path)
        linearization, commit_metadata, allocator = self._allocator_and_metadata(repo, real_db)

        for _ in range(3):
            mcp_server._reverse_fill_claim_and_process(
                real_db, str(repo), linearization, commit_metadata, allocator,
            )

        fn_ident = mcp_server._code_ident("function", "auth.py", "login")
        oldest_hash, mid_hash, newest_hash = linearization[0], linearization[1], linearization[2]
        assert mcp_server._entity_introduced_by_query(real_db, fn_ident) == f":commit/{oldest_hash[:12]}"
        assert mcp_server._lineage_is_provisional(real_db, fn_ident) is True
        raw = mcp_server._db_execute(
            real_db, f"(query [:find (count ?c) :where [{fn_ident} :introduced-by ?c]])"
        )
        assert json.loads(raw)["results"] == [[1]]

        # The converged :modified-in set must match what forward walk would
        # have produced: every later touch except the true introduction
        # commit itself (h0 gets none -- see the design spec's corrected
        # "Per-commit algorithm" section and the final whole-branch
        # review's Critical finding #1 that this test was added to catch).
        raw = mcp_server._db_execute(
            real_db, f"(query [:find ?c :where [{fn_ident} :modified-in ?c]])"
        )
        modified_in_commits = {row[0] for row in json.loads(raw)["results"]}
        assert modified_in_commits == {f":commit/{mid_hash[:12]}", f":commit/{newest_hash[:12]}"}

    def test_two_entities_in_one_commit_get_different_classifications(self, real_db, tmp_path):
        """A single claimed commit can simultaneously introduce a brand-new
        entity and add a real touch to an already-authoritative one --
        the two must not cross-contaminate each other's handling."""
        import mcp_server
        repo = self._repo_with_evolving_function(tmp_path)
        linearization, commit_metadata, allocator = self._allocator_and_metadata(repo, real_db)

        extra_ident = mcp_server._code_ident("function", "auth.py", "extra")
        # Simulate Stream 1 having already confirmed extra() authoritatively,
        # before Stream 2 ever runs -- extra() first appears at h1, and this
        # commit (h2, claimed first) also touches it (its body is identical
        # at h1/h2, but it still shares the file with a genuinely new touch).
        mcp_server._transact(
            real_db, f"[[{extra_ident} :introduced-by :commit/preexisting]]", "2025-01-01T00:00:00Z",
        )

        claimed_hash = mcp_server._reverse_fill_claim_and_process(
            real_db, str(repo), linearization, commit_metadata, allocator,
        )
        commit_ident = f":commit/{claimed_hash[:12]}"

        more_ident = mcp_server._code_ident("function", "auth.py", "more")
        # more() is genuinely new at h2 -- first sighting, provisional.
        assert mcp_server._entity_introduced_by_query(real_db, more_ident) == commit_ident
        assert mcp_server._lineage_is_provisional(real_db, more_ident) is True

        # extra() stays authoritative and untouched on :introduced-by.
        assert mcp_server._entity_introduced_by_query(real_db, extra_ident) == ":commit/preexisting"
        assert mcp_server._lineage_is_provisional(real_db, extra_ident) is False

    def test_already_authoritative_entity_only_gets_modified_in(self, real_db, tmp_path):
        import mcp_server
        repo = self._repo_with_evolving_function(tmp_path)
        linearization, commit_metadata, allocator = self._allocator_and_metadata(repo, real_db)

        fn_ident = mcp_server._code_ident("function", "auth.py", "login")
        # Simulate Stream 1 having already confirmed login() authoritatively
        # at the oldest commit, before Stream 2 ever runs -- with a live
        # :ident alongside :introduced-by, matching what a real confirmation
        # always writes together (#231: the reverse walk's known-entity gate
        # keys on :ident liveness, not :introduced-by alone).
        mcp_server._transact(
            real_db,
            f'[[{fn_ident} :introduced-by :commit/preexisting] [{fn_ident} :ident "{fn_ident}"]]',
            "2025-01-01T00:00:00Z",
        )

        claimed_hash = mcp_server._reverse_fill_claim_and_process(
            real_db, str(repo), linearization, commit_metadata, allocator,
        )
        commit_ident = f":commit/{claimed_hash[:12]}"

        assert mcp_server._entity_introduced_by_query(real_db, fn_ident) == ":commit/preexisting"
        assert mcp_server._lineage_is_provisional(real_db, fn_ident) is False
        raw = mcp_server._db_execute(
            real_db, f"(query [:find ?c :where [{fn_ident} :modified-in ?c]])"
        )
        assert [commit_ident] in json.loads(raw)["results"]

    def test_frontier_high_interval_advances_by_one(self, real_db, tmp_path):
        import mcp_server
        import frontier_registry
        repo = self._repo_with_evolving_function(tmp_path)
        linearization, commit_metadata, allocator = self._allocator_and_metadata(repo, real_db)

        mcp_server._reverse_fill_claim_and_process(
            real_db, str(repo), linearization, commit_metadata, allocator,
        )

        bounds = mcp_server._frontier_read_bounds(real_db, mcp_server._FRONTIER_HIGH_IDENT)
        assert bounds is not None
        _lo_hash, hi_hash = bounds
        assert hi_hash == linearization[-1]


class TestReverseApplySplit:
    def test_split_pieces_compose_to_the_same_graph_as_the_wrapper(self, tmp_path):
        """Two independent graphs from one repo fixture -- the walk mutates
        the state a second run would start from, so this cannot be two
        passes over one graph."""
        import mcp_server, frontier_registry
        from minigraf import MiniGrafDb

        repo = tmp_path / "repo"
        repo.mkdir()
        _subprocess.run(["git", "init"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.email", "t@t.com"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.name", "T"], cwd=repo, check=True, capture_output=True)
        (repo / "auth.py").write_text("def login():\n    return 1\n")
        _subprocess.run(["git", "add", "."], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "commit", "-m", "h0"], cwd=repo, check=True, capture_output=True)

        linearization = frontier_registry.build_linearization(str(repo))
        commit_metadata = mcp_server._git_commits(str(repo), watermark_hash=None)

        def snapshot(db):
            raw = mcp_server._db_execute(db, "(query [:find ?e ?a ?v :where [?e ?a ?v]])")
            return sorted(tuple(row) for row in json.loads(raw)["results"])

        db_a = MiniGrafDb.open(str(tmp_path / "a.graph"))
        alloc_a = mcp_server._frontier_load(db_a, linearization, "2026-01-04T00:00:00Z")
        mcp_server._reverse_fill_claim_and_process(
            db_a, str(repo), linearization, commit_metadata, alloc_a,
        )

        db_b = MiniGrafDb.open(str(tmp_path / "b.graph"))
        alloc_b = mcp_server._frontier_load(db_b, linearization, "2026-01-04T00:00:00Z")
        pos = alloc_b.claim_high()
        file_results, _g, _m, _r = mcp_server._extract_commit(str(repo), linearization[pos], ())
        applied = mcp_server._reverse_apply(
            db_b, str(repo), linearization, commit_metadata, pos, file_results,
        )
        assert applied == linearization[pos]
        assert snapshot(db_a) == snapshot(db_b)

    def test_retroactive_modified_in_is_grouped_by_superseded_timestamp(self, real_db, tmp_path):
        """#233: one transact per entity here was 10,161 calls over 12
        commits of this repo. Each edge carries the SUPERSEDED commit's
        timestamp, not this commit's, so one batch is impossible -- but
        entities in one file were almost always last sighted at the same
        commit, so grouping by timestamp collapses to a handful."""
        import mcp_server
        import frontier_registry
        repo = tmp_path / "repo"
        repo.mkdir()
        _subprocess.run(["git", "init"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.email", "t@t.com"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.name", "T"], cwd=repo, check=True, capture_output=True)
        bodies = "\n\n".join(f"def f{i}():\n    return 0" for i in range(12))
        for rev in range(2):
            if rev > 0:
                time.sleep(1.1)  # ensure distinct commit-timestamp seconds; see git_repo_with_deletion
            (repo / "wide.py").write_text(bodies.replace("return 0", f"return {rev}") + "\n")
            _subprocess.run(["git", "add", "."], cwd=repo, check=True, capture_output=True)
            _subprocess.run(["git", "commit", "-m", f"c{rev}"], cwd=repo, check=True, capture_output=True)
        linearization = frontier_registry.build_linearization(str(repo))
        commit_metadata = mcp_server._git_commits(str(repo), watermark_hash=None)
        allocator = mcp_server._frontier_load(real_db, linearization, "2026-01-04T00:00:00Z")
        # Claim the tip first so the second claim is a genuine move.
        mcp_server._reverse_fill_claim_and_process(
            real_db, str(repo), linearization, commit_metadata, allocator,
        )

        transacts = []
        real_transact = mcp_server._transact
        mcp_server._transact = lambda db_, facts, *a, **k: (
            transacts.append(facts) or real_transact(db_, facts, *a, **k)
        )
        try:
            mcp_server._reverse_fill_claim_and_process(
                real_db, str(repo), linearization, commit_metadata, allocator,
            )
        finally:
            mcp_server._transact = real_transact

        retroactive = [f for f in transacts if ":modified-in" in f]
        assert len(retroactive) <= 2, (
            f"grouped by superseded timestamp, not one per entity; got {len(retroactive)}"
        )

    def test_grouped_retroactive_modified_in_keeps_every_edge(self, real_db, tmp_path):
        """Grouping must not lose edges -- these facts differ in entity, so
        they do not collide, but that is the assumption worth pinning."""
        import mcp_server
        import frontier_registry
        repo = tmp_path / "repo"
        repo.mkdir()
        _subprocess.run(["git", "init"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.email", "t@t.com"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.name", "T"], cwd=repo, check=True, capture_output=True)
        bodies = "\n\n".join(f"def f{i}():\n    return 0" for i in range(6))
        for rev in range(2):
            if rev > 0:
                time.sleep(1.1)  # ensure distinct commit-timestamp seconds; see git_repo_with_deletion
            (repo / "wide.py").write_text(bodies.replace("return 0", f"return {rev}") + "\n")
            _subprocess.run(["git", "add", "."], cwd=repo, check=True, capture_output=True)
            _subprocess.run(["git", "commit", "-m", f"c{rev}"], cwd=repo, check=True, capture_output=True)
        linearization = frontier_registry.build_linearization(str(repo))
        commit_metadata = mcp_server._git_commits(str(repo), watermark_hash=None)
        allocator = mcp_server._frontier_load(real_db, linearization, "2026-01-04T00:00:00Z")

        mcp_server._reverse_bulk_fill_walk(
            real_db, str(repo), linearization, commit_metadata, allocator,
        )

        tip_ident = f":commit/{linearization[1][:12]}"
        for i in range(6):
            ident = mcp_server._code_ident("function", "wide.py", f"f{i}")
            raw = mcp_server._db_execute(
                real_db, f"(query [:find ?c :where [{ident} :modified-in ?c]])"
            )
            modified_in = {row[0] for row in json.loads(raw)["results"]}
            assert tip_ident in modified_in, (
                f"{ident} lost its retroactive edge; got {sorted(modified_in)}"
            )

    def test_retroactive_gate_and_valid_time_survive_a_shared_superseded_timestamp(
        self, real_db, tmp_path
    ):
        """#233 review: all three per-ident gates are pure functions of
        superseded_ident (plus the fixed pos/commit_ident), and the group
        key superseded_ts is ALSO a pure function of superseded_ident -- so
        a group-wide implementation can only diverge from the per-ident one
        when two DISTINCT superseded commits share a timestamp SECOND. This
        pins two things at once against that exact fixture shape:

        (a) the superseded_pos <= pos refusal stays per-ident across a group
            boundary -- one ident's superseded guess (fake_before, position
            0) is refused, the other's (fake_after, position 2) is allowed,
            despite both sharing shared_ts, with the real commit processed
            at position 1 in between;
        (b) the allowed edge's valid-time is pinned to its OWN
            superseded_ts, not this commit's commit_ts_iso, checked via
            :valid-at against the real backend rather than by inspecting
            transact call arguments.

        commit_metadata/linearization are hand-extended with two fabricated
        commit idents around one real commit -- the same "no real git
        history, hand-built pos_by_commit_ident" shape
        test_monotonicity_refusal_is_per_ident_not_per_batch already uses
        for the sibling per-ident gate in
        _entity_introduced_by_set_provisional_batch, because the refusal
        branch guards a state (a "later" guess that turns out not to be
        later) normal monotonic reverse-walk traversal can never produce on
        its own.
        """
        import mcp_server
        import frontier_registry
        repo = tmp_path / "repo"
        repo.mkdir()
        _subprocess.run(["git", "init"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.email", "t@t.com"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.name", "T"], cwd=repo, check=True, capture_output=True)
        (repo / "a.py").write_text("def fa():\n    return 0\n")
        (repo / "b.py").write_text("def fb():\n    return 0\n")
        _subprocess.run(["git", "add", "."], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "commit", "-m", "root"], cwd=repo, check=True, capture_output=True)

        real_linearization = frontier_registry.build_linearization(str(repo))
        real_commit_metadata = mcp_server._git_commits(str(repo), watermark_hash=None)
        root_hash, _real_root_ts, root_author, root_subject = real_commit_metadata[0]
        assert real_linearization == [root_hash]

        # All hand-picked, ordered SEED_TS < commit_ts_iso < shared_ts, and
        # every one safely in minigraf's PAST relative to wall-clock "now"
        # (unlike the real git-derived timestamp, which is effectively
        # "now" and therefore too late to precede anything) -- because
        # _reverse_apply's own "is this entity already known" check
        # (_entity_introduced_by_query) is a PLAIN, now-relative query: a
        # future-dated seed would be invisible to it and the whole
        # provisional_moves path would never fire. See the #233 review
        # discussion (this was the first, silently-empty version of this
        # test) -- confirmed empirically against the real backend that a
        # plain query hides a future-valid_from fact but :valid-at does not.
        seed_ts = "2019-01-01T00:00:00Z"
        commit_ts_iso = "2020-01-01T00:00:00Z"  # this call's fabricated "current commit" time
        shared_ts = "2021-01-01T00:00:00Z"      # both fakes share this -- the collision under test

        fake_before_hash = "a" * 40  # position 0 -- superseded_pos (0) <= pos (1): refused
        fake_after_hash = "b" * 40   # position 2 -- superseded_pos (2) >  pos (1): allowed

        linearization = [fake_before_hash, root_hash, fake_after_hash]
        commit_metadata = [
            (fake_before_hash, shared_ts, "fake", "fake before"),
            (root_hash, commit_ts_iso, root_author, root_subject),
            (fake_after_hash, shared_ts, "fake", "fake after"),
        ]
        pos = 1

        fa_ident = mcp_server._code_ident("function", "a.py", "fa")
        fb_ident = mcp_server._code_ident("function", "b.py", "fb")
        fake_before_ident = f":commit/{fake_before_hash[:12]}"
        fake_after_ident = f":commit/{fake_after_hash[:12]}"

        # A real provisional guess always carries a live :ident, asserted at
        # the same sighting (#231: the reverse walk's known-entity gate keys
        # on :ident liveness, not :introduced-by alone).
        mcp_server._transact(
            real_db,
            f'[[{fa_ident} :ident "{fa_ident}"] [{fb_ident} :ident "{fb_ident}"]]',
            seed_ts,
        )
        # Seed both as already-provisional, guessed-introduced at the two
        # fabricated commits -- real writes through the real batch helper,
        # not a mock, mirroring test_monotonicity_refusal_is_per_ident_not_per_batch.
        mcp_server._entity_introduced_by_set_provisional_batch(
            real_db, [fa_ident], fake_before_ident, seed_ts,
        )
        mcp_server._entity_introduced_by_set_provisional_batch(
            real_db, [fb_ident], fake_after_ident, seed_ts,
        )

        file_results, _g, _m, _r = mcp_server._extract_commit(str(repo), root_hash, ())
        mcp_server._reverse_apply(
            real_db, str(repo), linearization, commit_metadata, pos, file_results,
        )

        # (a) fa's guess (fake_before, position 0) is refused: no
        # :modified-in fact at all, checked :valid-at shared_ts -- where a
        # wrongly-admitted one (grouped under shared_ts by a buggy
        # group-wide gate) would show.
        raw = mcp_server._db_execute(
            real_db,
            f'(query [:find ?c :valid-at "{shared_ts}" :where [{fa_ident} :modified-in ?c]])',
        )
        assert json.loads(raw)["results"] == [], (
            f"fa's refused superseded guess must not get a retroactive edge; "
            f"got {json.loads(raw)['results']}"
        )

        # fb's guess (fake_after, position 2) is allowed: exactly the one
        # retroactive edge, to fake_after_ident -- checked the same way, so
        # a buggy group-wide gate that drops the WHOLE group (because fa,
        # iterated first, was refused) is caught here too.
        raw = mcp_server._db_execute(
            real_db,
            f'(query [:find ?c :valid-at "{shared_ts}" :where [{fb_ident} :modified-in ?c]])',
        )
        modified_in = {row[0] for row in json.loads(raw)["results"]}
        assert modified_in == {fake_after_ident}, (
            f"fb's allowed superseded guess must get its retroactive edge; got {modified_in}"
        )

        # (b) valid-time: fb's edge reads as [] :valid-at commit_ts_iso (this
        # call's own commit) and live :valid-at shared_ts (fake_after's own
        # commit) -- pinned to the SUPERSEDED commit's timestamp, not this
        # commit's, exactly mirroring the real 4-commit/2-file reproduction
        # from the #233 review ("a-py-f0 :modified-in reads [] as-of c0's ts
        # and live as-of c1's").
        raw = mcp_server._db_execute(
            real_db,
            f'(query [:find ?c :valid-at "{commit_ts_iso}" :where [{fb_ident} :modified-in ?c]])',
        )
        assert json.loads(raw)["results"] == [], (
            "fb's retroactive edge must not be valid at commit_ts_iso "
            f"({commit_ts_iso}); got {json.loads(raw)['results']}"
        )


class _NoProgressAllocator:
    """Stand-in for a FrontierAllocator whose claim_high() stops making
    progress -- the pre-2b1 behaviour on a grown linearization, where
    _extend rewrote a stale interval to itself and gap_hi never moved.

    Not a mocked backend (docs/testing-conventions.md): the DB and the git
    repo in this test are real; only the allocator, a pure in-memory
    collaborator, is substituted, because after the 2b1 allocator fix no
    real allocator can reach this state -- which is exactly why the walk
    still needs its own guard.

    Raises rather than looping forever once called too many times, so a
    missing guard fails the test instead of hanging the suite.
    """

    def __init__(self, pos, max_calls=50):
        self.pos = pos
        self.calls = 0
        self.max_calls = max_calls

    def claim_high(self):
        self.calls += 1
        if self.calls > self.max_calls:
            raise AssertionError(
                f"claim_high() called {self.calls} times without progress -- "
                "_reverse_bulk_fill_walk has no progress guard"
            )
        return self.pos


class _SimulatedKill(Exception):
    """Stands in for the SIGKILL in #313's reproduction. Raised from inside
    _reverse_apply's write sequence so the facts already transacted stay in
    the graph exactly as a hard-killed process leaves them."""


class TestReverseApplyTornWriteResume:
    """#313: a commit's reverse-stream write is a SEQUENCE of _transact
    calls, not one atomic unit -- the structural facts (including the live
    :ident) land first, the provisional :introduced-by lands several calls
    later, and _frontier_persist_claim lands last. A run killed inside that
    window leaves the entity TORN: live :ident, no :introduced-by, no
    lineage marker, and the position still unclaimed in the frontier.

    Nothing downstream saw that state. On resume _reverse_apply re-claims
    the position, _entity_ident_is_live answers True, _lineage_is_provisional
    answers False (the marker never got written), and the entity fell into
    the already-authoritative branch -- which only ever considers
    :modified-in. The correction sweep could not repair it either: its case
    3 reads zero :introduced-by values as "ambiguous" and fail-safe skips.
    So the entity stayed orphaned forever while the run reported
    status: complete with zero bytes on stderr.

    Measured at 3 of 14 interrupted resumes on an 80-commit linear repo
    (SIGKILL at ~43 of 80, always the one commit sitting at the reverse
    stream's frontier), against 0 of 5 uninterrupted runs.
    """

    @staticmethod
    def _repo_with_one_commit(tmp_path):
        repo = tmp_path / "repo"
        repo.mkdir()
        _subprocess.run(["git", "init"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.email", "t@t.com"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.name", "T"], cwd=repo, check=True, capture_output=True)
        (repo / "auth.py").write_text("def login():\n    return 1\n")
        _subprocess.run(["git", "add", "."], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "commit", "-m", "h0"], cwd=repo, check=True, capture_output=True)
        return repo

    @staticmethod
    def _tear_then_resume(monkeypatch, real_db, repo):
        """Run _reverse_apply twice over position 0: once killed between the
        structural transact and the provisional-lineage batch, once whole.

        The tear is produced by the REAL write path rather than hand-seeded,
        so the resumed call sees precisely the fact set a killed process
        leaves behind -- a hand-built approximation would be free to omit
        whichever fact the bug turns on.
        """
        import mcp_server
        import frontier_registry

        linearization = frontier_registry.build_linearization(str(repo))
        commit_metadata = mcp_server._git_commits(str(repo), watermark_hash=None)
        pos = 0
        file_results, _g, _m, _r = mcp_server._extract_commit(str(repo), linearization[pos], ())

        def die(*_a, **_k):
            raise _SimulatedKill()

        with monkeypatch.context() as mp:
            mp.setattr(mcp_server, "_entity_introduced_by_set_provisional_batch", die)
            with pytest.raises(_SimulatedKill):
                mcp_server._reverse_apply(
                    real_db, str(repo), linearization, commit_metadata, pos, file_results,
                )

        commit_ident = f":commit/{linearization[pos][:12]}"
        return (
            commit_ident,
            lambda: mcp_server._reverse_apply(
                real_db, str(repo), linearization, commit_metadata, pos, file_results,
            ),
        )

    def test_resumed_commit_gives_lineage_to_an_entity_torn_by_the_kill(
        self, real_db, tmp_path, monkeypatch
    ):
        import mcp_server

        repo = self._repo_with_one_commit(tmp_path)
        fn_ident = mcp_server._code_ident("function", "auth.py", "login")
        mod_ident = mcp_server._code_ident("module", "auth.py")
        commit_ident, resume = self._tear_then_resume(monkeypatch, real_db, repo)

        # The tear is real, and it is the state the bug report describes:
        # the entity is live but holds no lineage at all. Asserted before
        # the resume so a kill point that drifts away from #313's window
        # fails here rather than silently making the test vacuous.
        for ident in (fn_ident, mod_ident):
            assert mcp_server._entity_ident_is_live(real_db, ident), (
                f"{ident} must be live after the interrupted write -- if it is not, the "
                "kill no longer lands after the structural transact and this test has "
                "stopped reproducing #313"
            )
            assert mcp_server._entity_introduced_by_values_query(real_db, ident) == [], (
                f"{ident} must hold no :introduced-by after the interrupted write"
            )
            assert not mcp_server._lineage_is_provisional(real_db, ident), (
                f"{ident} must have no lineage marker after the interrupted write"
            )

        resume()

        for ident in (fn_ident, mod_ident):
            values = mcp_server._entity_introduced_by_values_query(real_db, ident)
            assert values == [commit_ident], (
                f"{ident} was torn by the interrupted write and must be re-introduced at "
                f"{commit_ident} by the resumed run; got {values}"
            )
            assert mcp_server._lineage_is_provisional(real_db, ident), (
                f"{ident}'s recovered :introduced-by is a reverse-stream GUESS and must "
                "carry a lineage marker, or the correction sweep reads it as "
                "authoritative and never confirms it"
            )

    def test_torn_entity_is_not_also_recorded_as_modified_in_that_commit(
        self, real_db, tmp_path, monkeypatch
    ):
        """The recovered entity is INTRODUCED at this commit, so it must not
        also be recorded as modified in it -- the self-introduction invariant
        every other introduction path holds. Pins that the repair routes the
        ident through the new-candidate path rather than bolting an
        :introduced-by onto the already-authoritative branch, which would
        emit :modified-in alongside it.
        """
        import mcp_server

        repo = self._repo_with_one_commit(tmp_path)
        fn_ident = mcp_server._code_ident("function", "auth.py", "login")
        commit_ident, resume = self._tear_then_resume(monkeypatch, real_db, repo)
        resume()

        raw = mcp_server._db_execute(
            real_db, f"(query [:find ?c :where [{fn_ident} :modified-in ?c]])"
        )
        assert json.loads(raw)["results"] == [], (
            f"{fn_ident} is introduced at {commit_ident}; it must not also be recorded "
            f"as modified there, got {json.loads(raw)['results']}"
        )


class TestSkipFastPathDoesNotSkipTornWrites:
    """#326 acceptance test 2, and the one that matters. A fast path whose
    predicate quietly matched nothing would pass the skip test by doing no
    skipping at all; this is the test that would catch the OPPOSITE error.

    #325 words the fast path as skipping a position whose :commit/<hash> entity
    already exists. That entity is the FIRST element of _reverse_apply's
    all_triples, written before any file result is looked at, while
    _frontier_persist_claim runs LAST -- so it is present on exactly the torn
    positions #313 needs re-walked. Skipping one would make the orphaned lineage
    permanent, surfacing later as #316's entities_without_introduced_by going
    red on a graph with no other symptom, or on an older graph not at all.
    """

    def _tear_position_zero(self, monkeypatch, real_db, repo):
        """Tear position 0 through the REAL write path -- kill the lineage batch
        mid-_reverse_apply, exactly as TestReverseApplyTornWriteResume does, so
        nothing here depends on hitting a timing window."""
        import mcp_server
        import frontier_registry

        linearization = frontier_registry.build_linearization(str(repo))
        commit_metadata = mcp_server._git_commits(str(repo), watermark_hash=None)
        file_results, _g, _m, _r = mcp_server._extract_commit(str(repo), linearization[0], ())

        def die(*_a, **_k):
            raise _SimulatedKill()

        with monkeypatch.context() as mp:
            mp.setattr(mcp_server, "_entity_introduced_by_set_provisional_batch", die)
            with pytest.raises(_SimulatedKill):
                mcp_server._reverse_apply(
                    real_db, str(repo), linearization, commit_metadata, 0, file_results,
                )
        return linearization

    @staticmethod
    def _repo_with_independent_commits(tmp_path, n):
        """n commits, each touching its OWN file and function -- unlike
        TestReverseFillResumeOnGrownLinearization._repo, which rewrites the same
        function every commit so later positions keep moving its lineage guess
        earlier. Independence means walking positions above 0 cannot touch
        position 0's entity at all, so tearing position 0 afterward still
        reproduces the classic #313 shape (live entity, ZERO :introduced-by)
        rather than a guess that merely failed to move."""
        repo = tmp_path / "repo"
        repo.mkdir()
        _subprocess.run(["git", "init"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.email", "t@t.com"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.name", "T"], cwd=repo, check=True, capture_output=True)
        for i in range(n):
            (repo / f"e{i}.py").write_text(f"def fn{i}():\n    return {i}\n")
            _subprocess.run(["git", "add", "."], cwd=repo, check=True, capture_output=True)
            _subprocess.run(["git", "commit", "-m", f"c{i}"], cwd=repo, check=True, capture_output=True)
        return repo

    def test_a_torn_position_is_in_no_archived_region(self, real_db, tmp_path, monkeypatch):
        """The soundness argument, demonstrated against a REAL archived region
        rather than an always-empty one. Positions 3, 2, 1 are walked normally
        (each completes and persists its claim, from the tip down -- the shape
        _frontier_persist_claim's from_low=False produces), then archived as a
        completed region exactly as _frontier_load does on a discard. Position
        0 is torn instead of walked.

        Two assertions, and the second is what makes the first mean something:
        without it, `_skip_claim("rev", 0, regions) is False` would pass just
        as well against an empty region list, which was this test's original
        defect -- a torn position reading as "not skipped" for a reason that
        has nothing to do with the tear. Asserting a genuinely-completed
        position from the SAME region reads True proves the region is real and
        non-empty, so the False above is about the boundary, not about an
        empty list.
        """
        import mcp_server

        n = 4
        repo = self._repo_with_independent_commits(tmp_path, n)
        linearization = frontier_registry.build_linearization(str(repo))
        commit_metadata = mcp_server._git_commits(str(repo), watermark_hash=None)
        fn0_ident = mcp_server._code_ident("function", "e0.py", "fn0")

        for pos in range(n - 1, 0, -1):  # 3, 2, 1 -- upper positions, tip down
            file_results, _g, _m, _r = mcp_server._extract_commit(str(repo), linearization[pos], ())
            mcp_server._reverse_apply(
                real_db, str(repo), linearization, commit_metadata, pos, file_results,
            )

        high_bounds_before_tear = mcp_server._frontier_read_bounds(
            real_db, mcp_server._FRONTIER_HIGH_IDENT
        )
        assert high_bounds_before_tear == (linearization[1], linearization[3]), (
            "positions 3, 2, 1 must have completed and persisted their claims, "
            "or there is no genuine completed region to archive"
        )

        file_results_0, _g, _m, _r = mcp_server._extract_commit(str(repo), linearization[0], ())

        def die(*_a, **_k):
            raise _SimulatedKill()

        with monkeypatch.context() as mp:
            mp.setattr(mcp_server, "_entity_introduced_by_set_provisional_batch", die)
            with pytest.raises(_SimulatedKill):
                mcp_server._reverse_apply(
                    real_db, str(repo), linearization, commit_metadata, 0, file_results_0,
                )

        # The tear is real, and it is the state the bug report describes --
        # asserted before it is relied on, so a kill point that drifts away
        # from #313's window fails here rather than silently making the rest
        # of this test vacuous.
        assert mcp_server._entity_ident_is_live(real_db, fn0_ident), (
            f"{fn0_ident} must be live after the interrupted write -- if it is "
            "not, the kill no longer lands after the structural transact and "
            "this test has stopped reproducing #313"
        )
        assert mcp_server._entity_introduced_by_values_query(real_db, fn0_ident) == [], (
            f"{fn0_ident} must hold no :introduced-by after the interrupted write"
        )
        assert mcp_server._frontier_read_bounds(
            real_db, mcp_server._FRONTIER_HIGH_IDENT
        ) == high_bounds_before_tear, (
            "the torn write must not have persisted a claim -- the archived "
            "high bound must still stop at position 1, never reach position 0"
        )

        mcp_server._completed_region_record(
            real_db, linearization[1], linearization[3], ":provisional",
            "2026-01-01T00:00:00Z",
            order={h: i for i, h in enumerate(linearization)},
        )
        regions = mcp_server._completed_regions_load(
            real_db, linearization,
            frontier_registry.FrontierAllocator(len(linearization), []),
        )
        assert any(
            iv.tag == frontier_registry.TAG_PROVISIONAL and iv.lo_pos == 1 and iv.hi_pos == 3
            for iv in regions
        ), f"expected an archived provisional region [1, 3]; got {regions}"

        assert mcp_server._skip_claim("rev", 2, regions) is True, (
            "position 2 genuinely completed inside the archived region and must "
            "be skippable -- if this is False the region carries no weight and "
            "the assertion below proves nothing about a boundary"
        )
        assert mcp_server._skip_claim("rev", 0, regions) is False, (
            "the torn position must be re-walked; skipping it makes #313's "
            "orphaned lineage permanent"
        )

    def test_the_unsound_commit_entity_predicate_WOULD_have_skipped_it(
        self, real_db, tmp_path, monkeypatch
    ):
        """The trap is real, not hypothetical. Pins that the commit entity IS
        present on a torn position -- so this test goes red the day someone
        'simplifies' _skip_claim to the lookup #325 proposed."""
        import mcp_server

        repo = TestReverseApplyTornWriteResume._repo_with_one_commit(tmp_path)
        linearization = self._tear_position_zero(monkeypatch, real_db, repo)

        commit_ident = f":commit/{linearization[0][:12]}"
        raw = mcp_server._db_execute(
            real_db,
            f"(query [:find ?t :where [{commit_ident} :entity-type ?t]])",
        )
        assert json.loads(raw)["results"], (
            "the commit entity must be present on the torn position -- if it is "
            "not, the kill no longer lands after the first transact and this "
            "test has stopped guarding the predicate #326 rejected"
        )

    def test_the_torn_position_still_recovers_its_lineage_when_re_walked(
        self, real_db, tmp_path, monkeypatch
    ):
        """End of the chain: not skipped, therefore re-walked, therefore
        repaired -- #313's fix still reachable with the fast path in place."""
        import mcp_server

        repo = TestReverseApplyTornWriteResume._repo_with_one_commit(tmp_path)
        fn_ident = mcp_server._code_ident("function", "auth.py", "login")
        linearization = self._tear_position_zero(monkeypatch, real_db, repo)
        commit_metadata = mcp_server._git_commits(str(repo), watermark_hash=None)
        file_results, _g, _m, _r = mcp_server._extract_commit(str(repo), linearization[0], ())

        assert mcp_server._entity_introduced_by_values_query(real_db, fn_ident) == []
        mcp_server._reverse_apply(
            real_db, str(repo), linearization, commit_metadata, 0, file_results,
        )
        assert mcp_server._entity_introduced_by_values_query(real_db, fn_ident) == [
            f":commit/{linearization[0][:12]}"
        ]


class TestReverseBulkFillWalkProgressGuard:
    def test_breaks_loudly_when_claim_high_stops_decreasing(self, real_db, tmp_path, capsys):
        """The walk's loop is unbounded by construction and drives a git
        subprocess, a tree-sitter parse, a DB write batch and a
        _db_checkpoint fsync per iteration, inside what 2d intends to run as
        a background task. It must stop on its own if the allocator ever
        stops making progress, rather than spinning."""
        import mcp_server
        import frontier_registry
        repo = tmp_path / "repo"
        repo.mkdir()
        _subprocess.run(["git", "init"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.email", "t@t.com"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.name", "T"], cwd=repo, check=True, capture_output=True)
        for i in range(3):
            (repo / f"f{i}.py").write_text(f"def f{i}(): pass\n")
            _subprocess.run(["git", "add", "."], cwd=repo, check=True, capture_output=True)
            _subprocess.run(["git", "commit", "-m", f"h{i}"], cwd=repo, check=True, capture_output=True)
        linearization = frontier_registry.build_linearization(str(repo))
        commit_metadata = mcp_server._git_commits(str(repo), watermark_hash=None)
        allocator = _NoProgressAllocator(pos=1)

        count = mcp_server._reverse_bulk_fill_walk(
            real_db, str(repo), linearization, commit_metadata, allocator,
        )

        assert allocator.calls < 10, f"walk kept claiming after no progress ({allocator.calls} calls)"
        assert count >= 1  # the first claim is legitimate work
        assert "progress" in capsys.readouterr().err.lower()


def _assert_no_modified_in_at_or_before_introduction(db, linearization):
    """Cross-cutting invariant: no entity may carry a :modified-in at a
    position earlier than, or equal to, its :introduced-by's position.

    Forward walk cannot produce either shape -- _build_code_triples emits
    :modified-in only on its already-known branch, never at introduction --
    so both are pure reverse-walk corruption. Positions, never timestamps:
    ingest :date values are AUTHOR dates (_git_commits reads `%at`) and are
    not monotonic in topological order (this repo's own history has a
    six-day inversion), which is why build_linearization uses
    --topo-order in the first place.
    """
    import mcp_server
    pos_by_ident = {f":commit/{h[:12]}": i for i, h in enumerate(linearization)}
    raw = mcp_server._db_execute(
        db,
        "(query [:find ?e ?intro ?mod :where "
        "[?e :introduced-by ?intro] [?e :modified-in ?mod]])",
    )
    violations = []
    for entity, intro_ident, mod_ident in json.loads(raw)["results"]:
        intro_pos = pos_by_ident.get(intro_ident)
        mod_pos = pos_by_ident.get(mod_ident)
        if intro_pos is None or mod_pos is None:
            continue
        if mod_pos <= intro_pos:
            violations.append((entity, intro_ident, intro_pos, mod_ident, mod_pos))
    assert not violations, (
        "entities modified at or before their own introduction: " + repr(violations)
    )


class TestEntityIntroducedBySetProvisionalMonotonicity:
    def test_refuses_to_move_a_guess_to_a_later_commit(self, real_db):
        """The helper's contract is 'move the guess DOWN' -- its docstring
        says reverse walk has reached an *earlier* commit -- but nothing
        enforced it, so a re-claim of a higher position dragged the guess
        upward and left :modified-in edges stranded before it."""
        import mcp_server
        ident = ":function/f"
        pos_by = {":commit/c0": 0, ":commit/c1": 1, ":commit/c4": 4}
        mcp_server._entity_introduced_by_set_provisional(
            real_db, ident, ":commit/c1", "2026-01-02T00:00:00Z",
            pos=1, pos_by_commit_ident=pos_by,
        )
        mcp_server._entity_introduced_by_set_provisional(
            real_db, ident, ":commit/c4", "2026-01-05T00:00:00Z",
            pos=4, pos_by_commit_ident=pos_by,
        )
        assert mcp_server._entity_introduced_by_query(real_db, ident) == ":commit/c1"

    def test_still_moves_a_guess_to_an_earlier_commit(self, real_db):
        import mcp_server
        ident = ":function/f"
        pos_by = {":commit/c0": 0, ":commit/c1": 1, ":commit/c4": 4}
        mcp_server._entity_introduced_by_set_provisional(
            real_db, ident, ":commit/c4", "2026-01-05T00:00:00Z",
            pos=4, pos_by_commit_ident=pos_by,
        )
        mcp_server._entity_introduced_by_set_provisional(
            real_db, ident, ":commit/c0", "2026-01-01T00:00:00Z",
            pos=0, pos_by_commit_ident=pos_by,
        )
        assert mcp_server._entity_introduced_by_query(real_db, ident) == ":commit/c0"


class TestReverseFillValidTimeParity:
    def _repo_with_three_commits(self, tmp_path):
        repo = tmp_path / "repo"
        repo.mkdir()
        _subprocess.run(["git", "init"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.email", "t@t.com"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.name", "T"], cwd=repo, check=True, capture_output=True)
        for i in range(3):
            if i > 0:
                # ensure distinct commit-timestamp seconds; see
                # git_repo_with_deletion -- test_stage_a_alone_leaves_the_window_open
                # below distinguishes "structural facts valid from the newest
                # sighting" from "valid from the introduction", which collapses
                # to a false pass if all three commits land in the same second.
                time.sleep(1.1)
            (repo / "auth.py").write_text(f"def login():\n    return {i}\n")
            _subprocess.run(["git", "add", "."], cwd=repo, check=True, capture_output=True)
            _subprocess.run(["git", "commit", "-m", f"c{i}"], cwd=repo, check=True, capture_output=True)
        return repo

    def _attrs_at(self, real_db, entity_ident, ts_iso):
        import mcp_server
        raw = mcp_server._db_execute(
            real_db, f'(query [:find ?a :valid-at "{ts_iso}" :where [{entity_ident} ?a ?v]])'
        )
        return {row[0] for row in json.loads(raw)["results"]}

    def test_structural_facts_are_re_dated_by_the_correction_sweep(self, real_db, tmp_path):
        """2b wrote an entity's structural facts once, at the timestamp of
        the commit where the walk first SIGHTED it. That leaves a valid-time
        window where :introduced-by is live for an entity with no type, name
        or file -- so ":as-of the introduction" answers "this entity did not
        exist", while ":when was it introduced" answers with that very
        commit.

        #233 moved the repair from _reverse_apply (which did it on every
        provisional move: 48% of Stage A's wall time) to the correction
        sweep's confirm branch, which visits each entity's introduction
        exactly once. So the invariant now holds after Stage B, not after
        Stage A -- this test asserts the end state, and its negative
        counterpart below pins the Stage A window deliberately."""
        import mcp_server
        import frontier_registry
        repo = self._repo_with_three_commits(tmp_path)
        linearization = frontier_registry.build_linearization(str(repo))
        commit_metadata = mcp_server._git_commits(str(repo), watermark_hash=None)
        allocator = mcp_server._frontier_load(real_db, linearization, "2026-01-04T00:00:00Z")
        mcp_server._reverse_bulk_fill_walk(
            real_db, str(repo), linearization, commit_metadata, allocator,
        )

        mcp_server._correction_sweep_walk(
            real_db, str(repo), linearization, commit_metadata,
        )

        login = mcp_server._code_ident("function", "auth.py", "login")
        attrs = self._attrs_at(real_db, login, commit_metadata[0][1])
        assert ":introduced-by" in attrs
        assert ":entity-type" in attrs, (
            "an entity live at its own introduction must carry its structure there too; "
            f"got only {sorted(attrs)}"
        )
        assert ":file" in attrs

    def test_stage_a_alone_leaves_the_window_open(self, real_db, tmp_path):
        """The other half of the moved invariant. Deferring the re-date is a
        real behaviour change and the window it opens is deliberate, so pin
        it in both directions -- otherwise a future change could re-introduce
        eager re-dating (and its 48% cost) with the suite still green."""
        import mcp_server
        import frontier_registry
        repo = self._repo_with_three_commits(tmp_path)
        linearization = frontier_registry.build_linearization(str(repo))
        commit_metadata = mcp_server._git_commits(str(repo), watermark_hash=None)
        allocator = mcp_server._frontier_load(real_db, linearization, "2026-01-04T00:00:00Z")

        mcp_server._reverse_bulk_fill_walk(
            real_db, str(repo), linearization, commit_metadata, allocator,
        )

        login = mcp_server._code_ident("function", "auth.py", "login")
        assert mcp_server._entity_introduced_by_query(real_db, login) == \
            f":commit/{linearization[0][:12]}"
        assert mcp_server._lineage_is_provisional(real_db, login) is True
        attrs = self._attrs_at(real_db, login, commit_metadata[0][1])
        assert ":entity-type" not in attrs, (
            "Stage A must NOT re-date -- that is the amplification #233 removed"
        )

    def test_reverse_walk_issues_no_re_dating_writes(self, real_db, tmp_path):
        """The cost assertion behind the behaviour assertions above:
        _re_date_structural_facts must not be reached at all during Stage A.
        At 17,250 retracts over 12 real commits (~13ms each) this was the
        single largest line in the profile."""
        import mcp_server
        import frontier_registry
        repo = self._repo_with_three_commits(tmp_path)
        linearization = frontier_registry.build_linearization(str(repo))
        commit_metadata = mcp_server._git_commits(str(repo), watermark_hash=None)
        allocator = mcp_server._frontier_load(real_db, linearization, "2026-01-04T00:00:00Z")

        calls = []
        real_re_date = mcp_server._re_date_structural_facts
        mcp_server._re_date_structural_facts = lambda *a, **k: (
            calls.append(a) or real_re_date(*a, **k)
        )
        try:
            mcp_server._reverse_bulk_fill_walk(
                real_db, str(repo), linearization, commit_metadata, allocator,
            )
        finally:
            mcp_server._re_date_structural_facts = real_re_date

        assert calls == []


class TestReverseFillParentEdges:
    def test_claimed_commits_get_parent_edges(self, real_db, tmp_path):
        """The bootstrap `ancestor` rule is defined purely over :parent, so
        without these edges ancestor queries return nothing across the whole
        reverse-filled region. Forward walk writes them, one transact per
        parent (a merge commit has two, same EAVT reason as :contains)."""
        import mcp_server
        import frontier_registry
        repo = tmp_path / "repo"
        repo.mkdir()
        _subprocess.run(["git", "init"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.email", "t@t.com"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.name", "T"], cwd=repo, check=True, capture_output=True)
        for i in range(3):
            (repo / f"f{i}.py").write_text(f"def f{i}(): pass\n")
            _subprocess.run(["git", "add", "."], cwd=repo, check=True, capture_output=True)
            _subprocess.run(["git", "commit", "-m", f"c{i}"], cwd=repo, check=True, capture_output=True)
        linearization = frontier_registry.build_linearization(str(repo))
        commit_metadata = mcp_server._git_commits(str(repo), watermark_hash=None)
        allocator = mcp_server._frontier_load(real_db, linearization, "2026-01-04T00:00:00Z")

        mcp_server._reverse_bulk_fill_walk(
            real_db, str(repo), linearization, commit_metadata, allocator,
        )

        child = f":commit/{linearization[1][:12]}"
        parent = f":commit/{linearization[0][:12]}"
        raw = mcp_server._db_execute(real_db, f"(query [:find ?p :where [{child} :parent ?p]])")
        assert {row[0] for row in json.loads(raw)["results"]} == {parent}

    def test_root_commit_has_no_parent(self, real_db, tmp_path):
        import mcp_server
        import frontier_registry
        repo = tmp_path / "repo"
        repo.mkdir()
        _subprocess.run(["git", "init"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.email", "t@t.com"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.name", "T"], cwd=repo, check=True, capture_output=True)
        (repo / "a.py").write_text("def a(): pass\n")
        _subprocess.run(["git", "add", "."], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "commit", "-m", "c0"], cwd=repo, check=True, capture_output=True)
        linearization = frontier_registry.build_linearization(str(repo))
        commit_metadata = mcp_server._git_commits(str(repo), watermark_hash=None)
        allocator = mcp_server._frontier_load(real_db, linearization, "2026-01-04T00:00:00Z")

        mcp_server._reverse_bulk_fill_walk(
            real_db, str(repo), linearization, commit_metadata, allocator,
        )

        root = f":commit/{linearization[0][:12]}"
        raw = mcp_server._db_execute(real_db, f"(query [:find ?p :where [{root} :parent ?p]])")
        assert json.loads(raw)["results"] == []


class TestReverseFillCommitMetadataContract:
    def test_misaligned_commit_metadata_raises_instead_of_misattributing(self, real_db, tmp_path):
        """commit_metadata is indexed POSITIONALLY against linearization
        while _frontier_persist_claim persists linearization[pos], so a
        watermark-relative list (what _run_ingestion actually builds) makes
        2b attribute entities to one commit and persist another -- silent,
        systematic misattribution. 2b is handed a position by an allocator
        that already claimed it, so it cannot decline: it must raise."""
        import mcp_server
        import frontier_registry
        repo = tmp_path / "repo"
        repo.mkdir()
        _subprocess.run(["git", "init"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.email", "t@t.com"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.name", "T"], cwd=repo, check=True, capture_output=True)
        for i in range(3):
            (repo / f"f{i}.py").write_text(f"def f{i}(): pass\n")
            _subprocess.run(["git", "add", "."], cwd=repo, check=True, capture_output=True)
            _subprocess.run(["git", "commit", "-m", f"c{i}"], cwd=repo, check=True, capture_output=True)
        linearization = frontier_registry.build_linearization(str(repo))
        commit_metadata = mcp_server._git_commits(str(repo), watermark_hash=None)
        allocator = mcp_server._frontier_load(real_db, linearization, "2026-01-04T00:00:00Z")

        with pytest.raises(ValueError, match="commit_metadata"):
            mcp_server._reverse_fill_claim_and_process(
                real_db, str(repo), linearization, commit_metadata[1:], allocator,
            )


class TestReverseFillResumeOnGrownLinearization:
    """The 2b suite never exercised a resume at all -- every test built its
    allocator from a graph with no persisted frontier. This is the scenario
    the 2b review reproduced end to end: claim part of a repo, let new
    commits land, then run again."""

    def _repo(self, tmp_path, n):
        repo = tmp_path / "repo"
        if not repo.exists():
            repo.mkdir()
            _subprocess.run(["git", "init"], cwd=repo, check=True, capture_output=True)
            _subprocess.run(["git", "config", "user.email", "t@t.com"], cwd=repo, check=True, capture_output=True)
            _subprocess.run(["git", "config", "user.name", "T"], cwd=repo, check=True, capture_output=True)
        for i in range(n):
            (repo / "auth.py").write_text(f"def login():\n    return {i}\n")
            _subprocess.run(["git", "add", "."], cwd=repo, check=True, capture_output=True)
            _subprocess.run(["git", "commit", "-m", f"c{i}"], cwd=repo, check=True, capture_output=True)
        return repo

    def test_second_run_terminates_and_keeps_lineage_consistent(self, real_db, tmp_path):
        import mcp_server
        import frontier_registry
        repo = self._repo(tmp_path, 3)
        linearization = frontier_registry.build_linearization(str(repo))
        commit_metadata = mcp_server._git_commits(str(repo), watermark_hash=None)
        allocator = mcp_server._frontier_load(real_db, linearization, "2026-01-04T00:00:00Z")
        for _ in range(2):  # claim positions 2 and 1, leaving position 0
            mcp_server._reverse_fill_claim_and_process(
                real_db, str(repo), linearization, commit_metadata, allocator,
            )

        self._repo(tmp_path, 2)  # two more commits land on HEAD
        grown = frontier_registry.build_linearization(str(repo))
        grown_metadata = mcp_server._git_commits(str(repo), watermark_hash=None)
        assert len(grown) == 5
        allocator2 = mcp_server._frontier_load(real_db, grown, "2026-01-06T00:00:00Z")

        count = mcp_server._reverse_bulk_fill_walk(
            real_db, str(repo), grown, grown_metadata, allocator2,
        )

        assert count <= len(grown), f"walk re-claimed without progress ({count} commits)"
        high = mcp_server._frontier_read_bounds(real_db, mcp_server._FRONTIER_HIGH_IDENT)
        lo_pos, hi_pos = grown.index(high[0]), grown.index(high[1])
        assert lo_pos <= hi_pos, f"persisted frontier-high is inverted: {high}"
        _assert_no_modified_in_at_or_before_introduction(real_db, grown)

    def test_partial_second_run_does_not_drag_the_guess_forward(self, real_db, tmp_path):
        """The invariant has to hold at every persisted point, not only once
        a walk runs to exhaustion. A run that stops early -- crash, shutdown,
        or 2d simply yielding -- leaves whatever state the last claim wrote.
        Here run 1 leaves login's guess at position 1; run 2 then claims
        position 4 first, and without a monotonicity guard that DRAGS the
        guess up to 4 while the retroactive :modified-in lands at 1, i.e. an
        entity modified three commits before it was introduced."""
        import mcp_server
        import frontier_registry
        repo = self._repo(tmp_path, 3)
        linearization = frontier_registry.build_linearization(str(repo))
        commit_metadata = mcp_server._git_commits(str(repo), watermark_hash=None)
        allocator = mcp_server._frontier_load(real_db, linearization, "2026-01-04T00:00:00Z")
        for _ in range(2):
            mcp_server._reverse_fill_claim_and_process(
                real_db, str(repo), linearization, commit_metadata, allocator,
            )
        login = mcp_server._code_ident("function", "auth.py", "login")
        assert mcp_server._entity_introduced_by_query(real_db, login) == f":commit/{linearization[1][:12]}"

        self._repo(tmp_path, 2)
        grown = frontier_registry.build_linearization(str(repo))
        grown_metadata = mcp_server._git_commits(str(repo), watermark_hash=None)
        allocator2 = mcp_server._frontier_load(real_db, grown, "2026-01-06T00:00:00Z")
        for _ in range(2):  # partial: claim positions 4 and 3, then stop
            mcp_server._reverse_fill_claim_and_process(
                real_db, str(repo), grown, grown_metadata, allocator2,
            )

        _assert_no_modified_in_at_or_before_introduction(real_db, grown)
        intro = mcp_server._entity_introduced_by_query(real_db, login)
        assert intro == f":commit/{grown[1][:12]}", (
            f"guess moved forward to {intro}; it may only ever move earlier"
        )


class TestReverseFillContainsEdges:
    """Minigraf's EAVT pending index omits value bytes from the key, so
    several facts sharing (entity, attribute, valid_from) inside ONE
    transact collapse to the last one. Forward walk splits :contains out
    for exactly this reason (see _run_ingestion's own one-transact-per-edge
    loop); 2b batched everything, losing all but one containment edge per
    parent -- permanently, since no later phase rewrites :contains."""

    def _repo_with_multi_entity_file(self, tmp_path):
        repo = tmp_path / "repo"
        repo.mkdir()
        _subprocess.run(["git", "init"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.email", "t@t.com"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.name", "T"], cwd=repo, check=True, capture_output=True)
        (repo / "m.py").write_text(
            "class Acct:\n"
            "    bal = 0\n"
            "    rate = 1\n"
            "\n"
            "def a(): pass\n"
            "def b(): pass\n"
            "def c(): pass\n"
        )
        _subprocess.run(["git", "add", "."], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "commit", "-m", "h0"], cwd=repo, check=True, capture_output=True)
        return repo

    def _contains(self, db, parent_ident):
        import mcp_server
        raw = mcp_server._db_execute(db, f"(query [:find ?c :where [{parent_ident} :contains ?c]])")
        return {row[0] for row in json.loads(raw)["results"]}

    def test_every_entity_in_a_file_gets_its_containment_edge(self, real_db, tmp_path):
        import mcp_server
        import frontier_registry
        repo = self._repo_with_multi_entity_file(tmp_path)
        linearization = frontier_registry.build_linearization(str(repo))
        commit_metadata = mcp_server._git_commits(str(repo), watermark_hash=None)
        allocator = mcp_server._frontier_load(real_db, linearization, "2026-01-04T00:00:00Z")

        mcp_server._reverse_bulk_fill_walk(
            real_db, str(repo), linearization, commit_metadata, allocator,
        )

        module_ident = mcp_server._code_ident("module", "m.py")
        class_ident = mcp_server._code_ident("class", "m.py", "Acct")
        expected_module_children = {
            class_ident,
            mcp_server._code_ident("field", "m.py", "Acct.bal"),
            mcp_server._code_ident("field", "m.py", "Acct.rate"),
            mcp_server._code_ident("function", "m.py", "a"),
            mcp_server._code_ident("function", "m.py", "b"),
            mcp_server._code_ident("function", "m.py", "c"),
        }
        assert self._contains(real_db, module_ident) == expected_module_children
        assert self._contains(real_db, class_ident) == {
            mcp_server._code_ident("field", "m.py", "Acct.bal"),
            mcp_server._code_ident("field", "m.py", "Acct.rate"),
        }


class TestReverseBulkFillWalk:
    def test_walks_until_gap_closes_and_returns_count(self, real_db, tmp_path):
        import mcp_server
        import frontier_registry
        repo = tmp_path / "repo"
        repo.mkdir()
        _subprocess.run(["git", "init"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.email", "t@t.com"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.name", "T"], cwd=repo, check=True, capture_output=True)
        (repo / "a.py").write_text("def a(): pass\n")
        _subprocess.run(["git", "add", "."], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "commit", "-m", "h0"], cwd=repo, check=True, capture_output=True)
        (repo / "b.py").write_text("def b(): pass\n")
        _subprocess.run(["git", "add", "."], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "commit", "-m", "h1"], cwd=repo, check=True, capture_output=True)
        (repo / "c.py").write_text("def c(): pass\n")
        _subprocess.run(["git", "add", "."], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "commit", "-m", "h2"], cwd=repo, check=True, capture_output=True)

        linearization = frontier_registry.build_linearization(str(repo))
        commit_metadata = mcp_server._git_commits(str(repo), watermark_hash=None)
        allocator = mcp_server._frontier_load(real_db, linearization, "2026-01-04T00:00:00Z")

        count = mcp_server._reverse_bulk_fill_walk(
            real_db, str(repo), linearization, commit_metadata, allocator,
        )

        assert count == 3
        assert allocator.is_gap_empty() is True
        fn_ident_a = mcp_server._code_ident("function", "a.py", "a")
        assert mcp_server._entity_introduced_by_query(real_db, fn_ident_a) == f":commit/{linearization[0][:12]}"

    def test_gap_already_empty_returns_zero(self, real_db, tmp_path):
        import mcp_server
        import frontier_registry
        repo = tmp_path / "repo"
        repo.mkdir()
        _subprocess.run(["git", "init"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.email", "t@t.com"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.name", "T"], cwd=repo, check=True, capture_output=True)
        (repo / "a.py").write_text("def a(): pass\n")
        _subprocess.run(["git", "add", "."], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "commit", "-m", "h0"], cwd=repo, check=True, capture_output=True)

        linearization = frontier_registry.build_linearization(str(repo))
        commit_metadata = mcp_server._git_commits(str(repo), watermark_hash=None)
        allocator = mcp_server._frontier_load(real_db, linearization, "2026-01-02T00:00:00Z")
        while allocator.claim_low() is not None:
            pass  # drain the gap forward first

        count = mcp_server._reverse_bulk_fill_walk(
            real_db, str(repo), linearization, commit_metadata, allocator,
        )
        assert count == 0


class TestReverseApplyWriteBudget:
    """#233's regression test. The reverse walk was issuing ~6,970 write
    calls per commit against the forward walk's 12, because every per-entity
    write was per-entity-per-commit. Phase 2's fixtures were all 6-10
    commits and varied COMMIT count, so none of them could see it -- this
    varies ENTITY count at a fixed commit count, which is the axis the
    defect lived on."""

    def _repo_with_n_functions(self, tmp_path, n, name):
        repo = tmp_path / name
        repo.mkdir()
        _subprocess.run(["git", "init"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.email", "t@t.com"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.name", "T"], cwd=repo, check=True, capture_output=True)
        for rev in range(2):
            body = "\n\n".join(f"def f{i}():\n    return {rev}" for i in range(n))
            (repo / "wide.py").write_text(body + "\n")
            _subprocess.run(["git", "add", "."], cwd=repo, check=True, capture_output=True)
            _subprocess.run(["git", "commit", "-m", f"c{rev}"], cwd=repo, check=True, capture_output=True)
        return repo

    def _writes_for_the_second_claim(self, tmp_path, repo, graph_name):
        """Claim the tip (every entity is new), then count write calls for
        the claim below it (every entity is a provisional MOVE -- the path
        that scaled with entity count).

        Opens its own graph rather than reusing the real_db fixture's: this
        test runs two repos in one test body, and both name their file
        wide.py with functions f0.., so their idents would collide in a
        shared graph (and the second _frontier_load would read the first
        repo's now-stale bounds). The real_db fixture has already
        monkeypatched MiniGrafDb.open to hand back a fresh in-memory db per
        call, so open_db here is cheap and isolated."""
        import mcp_server
        import frontier_registry
        # Called twice per test (two repos, two graphs). A lease from the
        # PRIOR call (get_db()'s shim holds one until _reset_db_state())
        # would make the second open_db() here refuse to rebind to a
        # different path (#255's "cannot bind: lease(s) outstanding").
        mcp_server._reset_db_state()
        real_db = mcp_server.open_db(str(tmp_path / graph_name)) or mcp_server.get_db()
        linearization = frontier_registry.build_linearization(str(repo))
        commit_metadata = mcp_server._git_commits(str(repo), watermark_hash=None)
        allocator = mcp_server._frontier_load(real_db, linearization, "2026-01-04T00:00:00Z")
        mcp_server._reverse_fill_claim_and_process(
            real_db, str(repo), linearization, commit_metadata, allocator,
        )

        calls = []
        real_transact, real_retract = mcp_server._transact, mcp_server._retract
        mcp_server._transact = lambda *a, **k: (calls.append("t") or real_transact(*a, **k))
        mcp_server._retract = lambda *a, **k: (calls.append("r") or real_retract(*a, **k))
        try:
            mcp_server._reverse_fill_claim_and_process(
                real_db, str(repo), linearization, commit_metadata, allocator,
            )
        finally:
            mcp_server._transact, mcp_server._retract = real_transact, real_retract
        return len(calls)

    def test_per_commit_writes_do_not_scale_with_entity_count(self, real_db, tmp_path):
        small = self._writes_for_the_second_claim(
            tmp_path, self._repo_with_n_functions(tmp_path, 5, "small"), "small.graph"
        )
        large = self._writes_for_the_second_claim(
            tmp_path, self._repo_with_n_functions(tmp_path, 50, "large"), "large.graph"
        )

        assert large - small <= 5, (
            f"a 10x entity count must not multiply per-commit writes: "
            f"5 functions cost {small} write calls, 50 cost {large}. "
            f"Before #233 this ratio was ~10x."
        )

    def test_per_commit_writes_stay_in_the_forward_walk_s_range(self, real_db, tmp_path):
        """The absolute bar, not just the scaling one. The forward walk
        sustains ~12 writes per commit: one batched transact, one per
        :contains, one per :parent, watermark, checkpoint."""
        writes = self._writes_for_the_second_claim(
            tmp_path, self._repo_with_n_functions(tmp_path, 50, "wide"), "wide.graph"
        )

        assert writes <= 20, f"expected the forward walk's ~12 per commit; got {writes}"


class TestCorrectionSweepThroughWatermark:
    def test_unset_reads_as_none(self, real_db):
        import mcp_server
        assert mcp_server._correction_sweep_through_query(real_db) is None

    def test_update_then_query_round_trip(self, real_db):
        import mcp_server
        db = real_db
        mcp_server._correction_sweep_through_update(db, "h1", "2026-01-01T00:00:00Z")
        assert mcp_server._correction_sweep_through_query(db) == "h1"

        mcp_server._correction_sweep_through_update(db, "h2", "2026-01-02T00:00:00Z")
        assert mcp_server._correction_sweep_through_query(db) == "h2"

    def test_update_does_not_duplicate_hash_fact(self, real_db):
        import mcp_server
        db = real_db
        mcp_server._correction_sweep_through_update(db, "h1", "2026-01-01T00:00:00Z")
        mcp_server._correction_sweep_through_update(db, "h2", "2026-01-02T00:00:00Z")

        ident = mcp_server._CORRECTION_SWEEP_THROUGH_IDENT
        raw = mcp_server._db_execute(db, f"(query [:find (count ?h) :where [{ident} :hash ?h]])")
        assert json.loads(raw)["results"] == [[1]]

    def test_entity_carries_expected_constants_and_survives_audit(self, real_db):
        import mcp_server
        db = real_db
        mcp_server._correction_sweep_through_update(db, "h1", "2026-01-01T00:00:00Z")

        ident = mcp_server._CORRECTION_SWEEP_THROUGH_IDENT
        raw = mcp_server._db_execute(db, f"(query [:find ?a ?v :where [{ident} ?a ?v]])")
        attrs = dict(json.loads(raw)["results"])
        assert attrs[":entity-type"] == ":type/ingestion"
        assert attrs[":ident"] == ident
        assert isinstance(attrs[":description"], str) and attrs[":description"]

        result = mcp_server.handle_minigraf_audit()
        assert result["retracted"] == 0
        assert mcp_server._correction_sweep_through_query(db) == "h1"

    def test_description_is_distinct_from_lineage_confirmed_through(self, real_db):
        """Two :type/ingestion watermarks with byte-identical :description
        strings would both pass audit but be indistinguishable from each
        other in the fact index and in minigraf_audit output -- this
        watermark must not just copy lineage-confirmed-through's string."""
        import mcp_server
        db = real_db
        mcp_server._correction_sweep_through_update(db, "h1", "2026-01-01T00:00:00Z")
        mcp_server._lineage_confirmed_through_update(db, "h1", "2026-01-01T00:00:00Z")

        sweep_desc = dict(json.loads(mcp_server._db_execute(
            db, f"(query [:find ?a ?v :where [{mcp_server._CORRECTION_SWEEP_THROUGH_IDENT} ?a ?v]])"
        ))["results"])[":description"]
        lineage_desc = dict(json.loads(mcp_server._db_execute(
            db, f"(query [:find ?a ?v :where [{mcp_server._LINEAGE_CONFIRMED_THROUGH_IDENT} ?a ?v]])"
        ))["results"])[":description"]
        assert sweep_desc != lineage_desc


class TestCorrectionSweepSelectPosition:
    def _init_repo(self, repo):
        _subprocess.run(["git", "init"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.email", "t@t.com"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.name", "T"], cwd=repo, check=True, capture_output=True)

    def _commit(self, repo, filename, content, msg):
        (repo / filename).write_text(content)
        _subprocess.run(["git", "add", "."], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "commit", "-m", msg], cwd=repo, check=True, capture_output=True)

    def _repo_with_n_commits(self, tmp_path, n):
        repo = tmp_path / "repo"
        repo.mkdir()
        self._init_repo(repo)
        for i in range(n):
            self._commit(repo, f"f{i}.py", f"def f{i}(): pass\n", f"h{i}")
        return repo

    def _linearization_and_metadata(self, repo):
        import mcp_server
        import frontier_registry
        linearization = frontier_registry.build_linearization(str(repo))
        commit_metadata = mcp_server._git_commits(str(repo), watermark_hash=None)
        return linearization, commit_metadata

    def _close_gap(self, repo, real_db, linearization, commit_metadata):
        """Claim exactly one position from the low side via a real
        FrontierAllocator + _frontier_persist_claim (standing in for 2d's
        future ordinary forward walk), then claim the rest from the high
        side via 2b's real _reverse_fill_claim_and_process until the gap is
        empty. Claiming the *whole* gap from the low side alone (an
        unbounded claim_low() loop) would never touch frontier-high at
        all -- claim_low() alone can empty the gap without claim_high()
        ever running, since gap_hi only moves when claim_high() does -- so
        the low side must stop after a bounded number of claims for
        frontier-high to end up populated."""
        import mcp_server
        allocator = mcp_server._frontier_load(real_db, linearization, "2026-01-04T00:00:00Z")
        pos = allocator.claim_low()
        if pos is not None:
            mcp_server._frontier_persist_claim(
                real_db, linearization, pos, from_low=True, commit_ts_iso=commit_metadata[pos][1],
            )
        while not allocator.is_gap_empty():
            mcp_server._reverse_fill_claim_and_process(
                real_db, str(repo), linearization, commit_metadata, allocator,
            )
        return allocator

    def test_no_op_when_frontier_high_unclaimed(self, real_db, tmp_path):
        import mcp_server
        repo = self._repo_with_n_commits(tmp_path, 2)
        linearization, commit_metadata = self._linearization_and_metadata(repo)
        allocator = mcp_server._frontier_load(real_db, linearization, "2026-01-04T00:00:00Z")
        # Genuinely seed frontier-low (a fresh graph seeds neither side), so
        # this exercises "frontier-low exists, frontier-high doesn't".
        pos = allocator.claim_low()
        mcp_server._frontier_persist_claim(
            real_db, linearization, pos, from_low=True, commit_ts_iso=commit_metadata[pos][1],
        )

        result = mcp_server._correction_sweep_select_position(real_db, linearization, commit_metadata)
        assert result is None

    def test_no_op_while_gap_remains_open(self, real_db, tmp_path):
        """Direct regression test for the race the design spec's "Why
        confirming requires the gap to already be closed" section
        describes: claim only from the high side, leaving a non-empty gap
        below, and assert select_position refuses to hand out a position
        even though frontier-high has real claimed territory."""
        import mcp_server
        repo = self._repo_with_n_commits(tmp_path, 3)
        linearization, commit_metadata = self._linearization_and_metadata(repo)
        allocator = mcp_server._frontier_load(real_db, linearization, "2026-01-04T00:00:00Z")
        mcp_server._reverse_fill_claim_and_process(
            real_db, str(repo), linearization, commit_metadata, allocator,
        )
        assert allocator.is_gap_empty() is False  # only claimed the newest position so far

        result = mcp_server._correction_sweep_select_position(real_db, linearization, commit_metadata)
        assert result is None

    def test_runs_when_stream_2_claimed_everything_and_frontier_low_never_existed(
        self, real_db, tmp_path
    ):
        """A fresh graph seeds neither frontier side, and frontier-low is
        only created once the forward stream persists its first claim. If
        Stream 2 claims the whole history before Stream 1 claims anything
        -- entirely possible in 2d, since the forward stream does a large
        preload before its first claim -- the gap is genuinely closed
        (is_gap_empty() is True, claim_high() returns None forever) but
        frontier-low does not exist. Treating that as "nothing safe to do"
        strands every entity provisional for good, so an absent frontier-low
        must read as an EMPTY low region (its hi position is -1), not as an
        unknown one -- which is exactly what FrontierAllocator.gap_lo
        already does when no interval covers position 0."""
        import mcp_server
        repo = self._repo_with_n_commits(tmp_path, 3)
        linearization, commit_metadata = self._linearization_and_metadata(repo)
        allocator = mcp_server._frontier_load(real_db, linearization, "2026-01-04T00:00:00Z")
        while not allocator.is_gap_empty():
            mcp_server._reverse_fill_claim_and_process(
                real_db, str(repo), linearization, commit_metadata, allocator,
            )
        assert mcp_server._frontier_read_bounds(real_db, mcp_server._FRONTIER_LOW_IDENT) is None
        high = mcp_server._frontier_read_bounds(real_db, mcp_server._FRONTIER_HIGH_IDENT)
        assert high[0] == linearization[0]  # Stream 2 reached position 0

        result = mcp_server._correction_sweep_select_position(real_db, linearization, commit_metadata)
        assert result is not None, "gap is closed; the sweep must not refuse to run"
        assert result[0] == linearization[0]

    def test_returns_frontier_high_lo_hash_once_gap_closed(self, real_db, tmp_path):
        import mcp_server
        repo = self._repo_with_n_commits(tmp_path, 3)
        linearization, commit_metadata = self._linearization_and_metadata(repo)
        allocator = self._close_gap(repo, real_db, linearization, commit_metadata)
        assert allocator.is_gap_empty() is True

        result = mcp_server._correction_sweep_select_position(real_db, linearization, commit_metadata)
        assert result is not None
        commit_hash, commit_ts_iso = result
        bounds = mcp_server._frontier_read_bounds(real_db, mcp_server._FRONTIER_HIGH_IDENT)
        assert commit_hash == bounds[0]  # frontier-high's current lo-hash
        pos = linearization.index(commit_hash)
        assert commit_ts_iso == commit_metadata[pos][1]

    def test_resumes_from_correction_sweep_through_not_frontier_high_lo_hash(self, real_db, tmp_path):
        import mcp_server
        repo = self._repo_with_n_commits(tmp_path, 3)
        linearization, commit_metadata = self._linearization_and_metadata(repo)
        self._close_gap(repo, real_db, linearization, commit_metadata)

        first = mcp_server._correction_sweep_select_position(real_db, linearization, commit_metadata)
        assert first is not None
        first_hash, first_ts = first
        mcp_server._correction_sweep_through_update(real_db, first_hash, first_ts)

        second = mcp_server._correction_sweep_select_position(real_db, linearization, commit_metadata)
        assert second is not None
        second_hash, _second_ts = second
        assert second_hash != first_hash
        assert linearization.index(second_hash) == linearization.index(first_hash) + 1

    def test_no_op_once_reached_frontier_high_hi_hash(self, real_db, tmp_path):
        import mcp_server
        repo = self._repo_with_n_commits(tmp_path, 2)
        linearization, commit_metadata = self._linearization_and_metadata(repo)
        self._close_gap(repo, real_db, linearization, commit_metadata)

        # Walk to exhaustion by hand (Task 5 builds the real driving loop --
        # this test only needs select_position's own termination).
        while True:
            result = mcp_server._correction_sweep_select_position(real_db, linearization, commit_metadata)
            if result is None:
                break
            mcp_server._correction_sweep_through_update(real_db, result[0], result[1])

        assert mcp_server._correction_sweep_select_position(real_db, linearization, commit_metadata) is None

    def test_respects_persisted_hi_hash_not_len_linearization(self, real_db, tmp_path):
        """On an incremental re-ingest, linearization grows but frontier-
        high's persisted :hi-hash does not move with it -- the ceiling must
        stop at the persisted hash, not walk into brand-new, unclaimed
        commits."""
        import mcp_server
        repo = self._repo_with_n_commits(tmp_path, 2)
        linearization, commit_metadata = self._linearization_and_metadata(repo)
        self._close_gap(repo, real_db, linearization, commit_metadata)
        while True:
            result = mcp_server._correction_sweep_select_position(real_db, linearization, commit_metadata)
            if result is None:
                break
            mcp_server._correction_sweep_through_update(real_db, result[0], result[1])

        # Simulate an incremental re-ingest: more commits land, but neither
        # stream has claimed them yet.
        self._commit(repo, "new.py", "def new(): pass\n", "h_new")
        grown_linearization, grown_commit_metadata = self._linearization_and_metadata(repo)
        assert len(grown_linearization) == 3

        result = mcp_server._correction_sweep_select_position(
            real_db, grown_linearization, grown_commit_metadata
        )
        assert result is None

    def test_falls_back_to_frontier_high_lo_hash_when_stored_hash_is_stale(self, real_db, tmp_path):
        import mcp_server
        repo = self._repo_with_n_commits(tmp_path, 3)
        linearization, commit_metadata = self._linearization_and_metadata(repo)
        self._close_gap(repo, real_db, linearization, commit_metadata)
        mcp_server._correction_sweep_through_update(real_db, "deadbeef_not_in_linearization", "2026-01-01T00:00:00Z")

        result = mcp_server._correction_sweep_select_position(real_db, linearization, commit_metadata)
        assert result is not None
        commit_hash, _ts = result
        bounds = mcp_server._frontier_read_bounds(real_db, mcp_server._FRONTIER_HIGH_IDENT)
        assert commit_hash == bounds[0]

    def test_no_op_when_commit_metadata_violates_its_alignment_contract(self, real_db, tmp_path):
        """commit_metadata must be full-history and positionally aligned
        with linearization (i.e. _git_commits(repo, watermark_hash=None)).
        _run_ingestion builds a watermark-relative list instead, so a 2d
        wiring mistake would hand this function a shorter list -- which
        must return None rather than raise IndexError or, worse, read a
        different commit's metadata and write facts at the wrong
        timestamp."""
        import mcp_server
        repo = self._repo_with_n_commits(tmp_path, 3)
        linearization, commit_metadata = self._linearization_and_metadata(repo)
        self._close_gap(repo, real_db, linearization, commit_metadata)
        assert mcp_server._correction_sweep_select_position(
            real_db, linearization, commit_metadata
        ) is not None  # aligned metadata works

        truncated = commit_metadata[1:]  # what a watermark-relative list looks like
        assert mcp_server._correction_sweep_select_position(
            real_db, linearization, truncated
        ) is None

        # Right length, wrong order. Rotate rather than reverse: reversing an
        # odd-length list leaves the middle element in place, and that is
        # exactly the position _close_gap leaves the sweep pointing at, so a
        # reversed list would slip past the per-position hash check.
        misaligned = commit_metadata[1:] + commit_metadata[:1]
        assert mcp_server._correction_sweep_select_position(
            real_db, linearization, misaligned
        ) is None

    def test_hash_to_pos_reused_when_passed_in(self, real_db, tmp_path):
        """Smoke test that the hash_to_pos parameter is accepted: passing a
        correct, pre-built map still yields a valid result. This does not
        prove the function trusts the caller's map over recomputing its
        own -- it would pass identically either way."""
        import mcp_server
        repo = self._repo_with_n_commits(tmp_path, 2)
        linearization, commit_metadata = self._linearization_and_metadata(repo)
        self._close_gap(repo, real_db, linearization, commit_metadata)
        hash_to_pos = {h: i for i, h in enumerate(linearization)}

        result = mcp_server._correction_sweep_select_position(
            real_db, linearization, commit_metadata, hash_to_pos=hash_to_pos
        )
        assert result is not None


class TestCorrectionSweepDeclinesWhileFragmented:
    """#325: with a hole above frontier-high, Stream 2 can still descend past a
    position the sweep would confirm, so the sweep must decline."""

    def _seed(self, db, lin, extra=None, hi_idx=11):
        import mcp_server
        hi = mcp_server._FRONTIER_HIGH_IDENT
        lo = mcp_server._FRONTIER_LOW_IDENT
        mcp_server._transact(db, "[" + " ".join([
            f"[{lo} :entity-type :type/ingest-interval]",
            f"[{lo} :tag :authoritative]",
            f'[{lo} :lo-hash "{lin[0]}"]', f'[{lo} :hi-hash "{lin[3]}"]',
            f"[{lo} :pos-count 4]",
            f"[{hi} :entity-type :type/ingest-interval]",
            f"[{hi} :tag :provisional]",
            f'[{hi} :lo-hash "{lin[4]}"]', f'[{hi} :hi-hash "{lin[hi_idx]}"]',
            f"[{hi} :pos-count {hi_idx - 4 + 1}]",
        ]) + "]", "2026-09-04T00:00:00Z")
        if extra is not None:
            ident = mcp_server._interval_ident(lin[extra[1]])
            mcp_server._transact(db, "[" + " ".join([
                f"[{ident} :entity-type :type/ingest-interval]",
                f'[{ident} :ident "{ident}"]',
                f"[{ident} :tag :provisional]",
                f'[{ident} :lo-hash "{lin[extra[0]]}"]',
                f'[{ident} :hi-hash "{lin[extra[1]]}"]',
                f"[{ident} :pos-count {extra[1] - extra[0] + 1}]",
            ]) + "]", "2026-09-04T00:00:00Z")

    def _meta(self, lin):
        return [(h, "2026-09-04T00:00:00Z", "a", f"s{i}") for i, h in enumerate(lin)]

    def test_declines_while_a_hole_remains_above(self, real_db):
        import mcp_server
        lin = [f"h{i}" for i in range(14)]
        # frontier-high covers [4,7]; the extra covers [10,13] -- positions
        # 8-9 sit between the two as a genuine hole ABOVE frontier-high,
        # rather than the extra being nested INSIDE frontier-high's own
        # span (the previous fixture had frontier-high at [4,11] and an
        # extra at [9,11], entirely contained within it -- non-vacuous as a
        # positive control for the shipped "any extra exists" predicate,
        # but not the hole-above-frontier-high scenario this class is
        # named for).
        self._seed(real_db, lin, extra=(10, 13), hi_idx=7)
        assert mcp_server._correction_sweep_select_position(
            real_db, lin, self._meta(lin)) is None

    def test_selects_once_the_provisional_side_is_one_interval(self, real_db):
        import mcp_server
        lin = [f"h{i}" for i in range(12)]
        self._seed(real_db, lin)
        assert mcp_server._correction_sweep_select_position(
            real_db, lin, self._meta(lin)) == (lin[4], "2026-09-04T00:00:00Z")

    def test_fold_gate_declines_while_fragmented(self, real_db):
        import mcp_server
        lin = [f"h{i}" for i in range(14)]
        # Same genuine hole-above-frontier-high shape as
        # test_declines_while_a_hole_remains_above: frontier-high [4,7],
        # extra [10,13], positions 8-9 an unclaimed gap between them.
        self._seed(real_db, lin, extra=(10, 13), hi_idx=7)
        mcp_server._transact(
            real_db,
            f'[[:ingestion/correction-sweep-through :hash "{lin[7]}"]]',
            "2026-09-04T00:00:00Z")
        assert mcp_server._should_fold_lineage_watermark(real_db, lin) is False


class TestCorrectionSweepApply:
    def _init_repo(self, repo):
        _subprocess.run(["git", "init"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.email", "t@t.com"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.name", "T"], cwd=repo, check=True, capture_output=True)

    def _repo_with_evolving_function(self, tmp_path):
        """Three commits: login() genuinely changes body every commit (h0,
        h1, h2); extra() is added at h1 and left byte-identical at h2, so
        #221 marks it unchanged at h2 -- needed for the reconcile-retract
        test below."""
        repo = tmp_path / "repo"
        repo.mkdir()
        self._init_repo(repo)

        (repo / "auth.py").write_text("def login():\n    return 1\n")
        _subprocess.run(["git", "add", "."], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "commit", "-m", "h0"], cwd=repo, check=True, capture_output=True)

        (repo / "auth.py").write_text("def login():\n    return 2\n\ndef extra():\n    pass\n")
        _subprocess.run(["git", "add", "."], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "commit", "-m", "h1"], cwd=repo, check=True, capture_output=True)

        (repo / "auth.py").write_text(
            "def login():\n    return 3\n\ndef extra():\n    pass\n\ndef more():\n    pass\n"
        )
        _subprocess.run(["git", "add", "."], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "commit", "-m", "h2"], cwd=repo, check=True, capture_output=True)
        return repo

    def _extract(self, repo, commit_hash):
        import mcp_server
        file_results, _gitlink, _gitmodules, _renamed = mcp_server._extract_commit(str(repo), commit_hash, ())
        return file_results

    def test_confirms_correct_provisional_guess(self, real_db, tmp_path):
        import mcp_server
        import frontier_registry
        repo = self._repo_with_evolving_function(tmp_path)
        linearization = frontier_registry.build_linearization(str(repo))
        commit_metadata = mcp_server._git_commits(str(repo), watermark_hash=None)
        allocator = mcp_server._frontier_load(real_db, linearization, "2026-01-04T00:00:00Z")
        # Real reverse walk to the end so login()'s guess settles at h0 --
        # exactly TestReverseFillClaimAndProcess's own converged-state setup.
        for _ in range(3):
            mcp_server._reverse_fill_claim_and_process(
                real_db, str(repo), linearization, commit_metadata, allocator,
            )
        fn_ident = mcp_server._code_ident("function", "auth.py", "login")
        h0_hash, h0_ts = linearization[0], commit_metadata[0][1]
        assert mcp_server._entity_introduced_by_query(real_db, fn_ident) == f":commit/{h0_hash[:12]}"
        assert mcp_server._lineage_is_provisional(real_db, fn_ident) is True

        file_results = self._extract(repo, h0_hash)
        skipped = mcp_server._correction_sweep_apply(real_db, h0_hash, h0_ts, file_results)

        assert skipped == 0
        assert mcp_server._lineage_is_provisional(real_db, fn_ident) is False
        assert mcp_server._entity_introduced_by_query(real_db, fn_ident) == f":commit/{h0_hash[:12]}"

    def test_does_not_duplicate_commit_metadata(self, real_db, tmp_path):
        import mcp_server
        import frontier_registry
        repo = self._repo_with_evolving_function(tmp_path)
        linearization = frontier_registry.build_linearization(str(repo))
        commit_metadata = mcp_server._git_commits(str(repo), watermark_hash=None)
        allocator = mcp_server._frontier_load(real_db, linearization, "2026-01-04T00:00:00Z")
        for _ in range(3):
            mcp_server._reverse_fill_claim_and_process(
                real_db, str(repo), linearization, commit_metadata, allocator,
            )
        h0_hash, h0_ts = linearization[0], commit_metadata[0][1]
        commit_ident = f":commit/{h0_hash[:12]}"
        before_raw = mcp_server._db_execute(
            real_db, f"(query [:find ?a ?v :where [{commit_ident} ?a ?v]])"
        )
        before = sorted(json.loads(before_raw)["results"])

        file_results = self._extract(repo, h0_hash)
        mcp_server._correction_sweep_apply(real_db, h0_hash, h0_ts, file_results)

        after_raw = mcp_server._db_execute(
            real_db, f"(query [:find ?a ?v :where [{commit_ident} ?a ?v]])"
        )
        after = sorted(json.loads(after_raw)["results"])
        assert after == before

    def test_leaves_entity_untouched_when_guess_points_elsewhere(self, real_db, tmp_path):
        import mcp_server
        repo = self._repo_with_evolving_function(tmp_path)
        commit_metadata = mcp_server._git_commits(str(repo), watermark_hash=None)
        h0_hash, h0_ts = commit_metadata[0][0], commit_metadata[0][1]
        h1_hash = commit_metadata[1][0]
        fn_ident = mcp_server._code_ident("function", "auth.py", "login")
        # Hand-construct a provisional guess pointing at the WRONG commit
        # for the one this call will visit -- simulating a precondition
        # violation directly rather than via a real interleaving.
        mcp_server._entity_introduced_by_set_provisional(real_db, fn_ident, f":commit/{h1_hash[:12]}", "2025-01-01T00:00:00Z")

        file_results = self._extract(repo, h0_hash)
        skipped = mcp_server._correction_sweep_apply(real_db, h0_hash, h0_ts, file_results)

        assert skipped >= 1
        assert mcp_server._lineage_is_provisional(real_db, fn_ident) is True
        assert mcp_server._entity_introduced_by_query(real_db, fn_ident) == f":commit/{h1_hash[:12]}"

    def test_fails_safe_on_duplicate_introduced_by_h0_asserted_first(self, real_db, tmp_path):
        """Two live :introduced-by facts for one entity (the uncoordinated-
        forward-walk state the design spec defers to 2d) must be a no-op
        regardless of which fact minigraf's query returns first -- tested
        here via physical assertion order, in a sibling test via the
        opposite order, since row order itself isn't observable/controllable
        from the test, only the insertion order that produces it."""
        import mcp_server
        repo = self._repo_with_evolving_function(tmp_path)
        commit_metadata = mcp_server._git_commits(str(repo), watermark_hash=None)
        h0_hash, h0_ts = commit_metadata[0][0], commit_metadata[0][1]
        h1_hash = commit_metadata[1][0]
        commit_ident_h0 = f":commit/{h0_hash[:12]}"
        fn_ident = mcp_server._code_ident("function", "auth.py", "login")
        file_results = self._extract(repo, h0_hash)

        mcp_server._transact(real_db, f"[[{fn_ident} :introduced-by {commit_ident_h0}]]", "2025-01-01T00:00:00Z")
        mcp_server._transact(real_db, f"[[{fn_ident} :introduced-by :commit/{h1_hash[:12]}]]", "2025-01-02T00:00:00Z")
        mcp_server._lineage_mark_provisional(real_db, fn_ident, "2025-01-01T00:00:00Z")

        skipped = mcp_server._correction_sweep_apply(real_db, h0_hash, h0_ts, file_results)

        assert skipped >= 1
        assert mcp_server._lineage_is_provisional(real_db, fn_ident) is True

    def test_fails_safe_on_duplicate_introduced_by_h1_asserted_first(self, real_db, tmp_path):
        import mcp_server
        repo = self._repo_with_evolving_function(tmp_path)
        commit_metadata = mcp_server._git_commits(str(repo), watermark_hash=None)
        h0_hash, h0_ts = commit_metadata[0][0], commit_metadata[0][1]
        h1_hash = commit_metadata[1][0]
        commit_ident_h0 = f":commit/{h0_hash[:12]}"
        fn_ident = mcp_server._code_ident("function", "auth.py", "login")
        file_results = self._extract(repo, h0_hash)

        mcp_server._transact(real_db, f"[[{fn_ident} :introduced-by :commit/{h1_hash[:12]}]]", "2025-01-02T00:00:00Z")
        mcp_server._transact(real_db, f"[[{fn_ident} :introduced-by {commit_ident_h0}]]", "2025-01-01T00:00:00Z")
        mcp_server._lineage_mark_provisional(real_db, fn_ident, "2025-01-01T00:00:00Z")

        skipped = mcp_server._correction_sweep_apply(real_db, h0_hash, h0_ts, file_results)

        assert skipped >= 1
        assert mcp_server._lineage_is_provisional(real_db, fn_ident) is True

    def test_skips_modified_in_at_own_introduction_commit_on_resumed_sweep(self, real_db, tmp_path):
        import mcp_server
        repo = self._repo_with_evolving_function(tmp_path)
        commit_metadata = mcp_server._git_commits(str(repo), watermark_hash=None)
        h0_hash, h0_ts = commit_metadata[0][0], commit_metadata[0][1]
        fn_ident = mcp_server._code_ident("function", "auth.py", "login")
        commit_ident = f":commit/{h0_hash[:12]}"
        mcp_server._entity_introduced_by_set_provisional(real_db, fn_ident, commit_ident, "2025-01-01T00:00:00Z")
        file_results = self._extract(repo, h0_hash)

        mcp_server._correction_sweep_apply(real_db, h0_hash, h0_ts, file_results)  # confirms (case 1)
        assert mcp_server._lineage_is_provisional(real_db, fn_ident) is False

        # Simulate a resumed sweep re-visiting the same commit (e.g. after a
        # crash between confirming and advancing correction-sweep-through).
        mcp_server._correction_sweep_apply(real_db, h0_hash, h0_ts, file_results)

        raw = mcp_server._db_execute(real_db, f"(query [:find ?c :where [{fn_ident} :modified-in ?c]])")
        assert [commit_ident] not in json.loads(raw)["results"]

    def test_ordinary_modification_is_idempotent_when_2b_already_agrees(self, real_db, tmp_path):
        import mcp_server
        repo = self._repo_with_evolving_function(tmp_path)
        commit_metadata = mcp_server._git_commits(str(repo), watermark_hash=None)
        h0_hash = commit_metadata[0][0]
        h1_hash, h1_ts = commit_metadata[1][0], commit_metadata[1][1]
        fn_ident = mcp_server._code_ident("function", "auth.py", "login")
        h1_ident = f":commit/{h1_hash[:12]}"
        # login() is already authoritative at h0, and 2b (or forward walk)
        # already wrote the correct :modified-in for h1's genuine change.
        mcp_server._transact(real_db, f"[[{fn_ident} :introduced-by :commit/{h0_hash[:12]}]]", "2025-01-01T00:00:00Z")
        mcp_server._transact(real_db, f"[[{fn_ident} :modified-in {h1_ident}]]", h1_ts)
        # auth.py's other h1 candidates (the module, and extra() which is
        # added at h1) are also already-authoritative in any real system --
        # 2b's real per-commit function assigns :introduced-by to every
        # candidate it discovers for a commit, including the module ident,
        # so give both a legitimate single-value authoritative fact here
        # too, rather than leaving them with zero :introduced-by values.
        module_ident = mcp_server._code_ident("module", "auth.py")
        extra_ident = mcp_server._code_ident("function", "auth.py", "extra")
        mcp_server._transact(real_db, f"[[{module_ident} :introduced-by :commit/{h0_hash[:12]}]]", "2025-01-01T00:00:00Z")
        mcp_server._transact(real_db, f"[[{extra_ident} :introduced-by {h1_ident}]]", "2025-01-01T00:00:00Z")

        file_results = self._extract(repo, h1_hash)
        skipped = mcp_server._correction_sweep_apply(real_db, h1_hash, h1_ts, file_results)

        assert skipped == 0
        raw = mcp_server._db_execute(
            real_db, f"(query [:find (count ?c) :where [{fn_ident} :modified-in ?c]])"
        )
        assert json.loads(raw)["results"] == [[1]]

    def test_retracts_2b_over_asserted_retroactive_modified_in(self, real_db, tmp_path):
        """extra() is byte-identical between h1 and h2 (see the fixture
        docstring), so #221 marks it unchanged at h2 -- but simulate 2b's
        documented limitation by asserting :modified-in there anyway, then
        assert this sweep retracts it once it reaches h2 in the ordinary
        (already-authoritative) path."""
        import mcp_server
        repo = self._repo_with_evolving_function(tmp_path)
        commit_metadata = mcp_server._git_commits(str(repo), watermark_hash=None)
        h1_hash = commit_metadata[1][0]
        h2_hash, h2_ts = commit_metadata[2][0], commit_metadata[2][1]
        extra_ident = mcp_server._code_ident("function", "auth.py", "extra")
        h1_ident = f":commit/{h1_hash[:12]}"
        h2_ident = f":commit/{h2_hash[:12]}"
        mcp_server._transact(real_db, f"[[{extra_ident} :introduced-by {h1_ident}]]", "2025-01-01T00:00:00Z")
        mcp_server._transact(real_db, f"[[{extra_ident} :modified-in {h2_ident}]]", h2_ts)  # 2b's over-assertion
        # auth.py's other h2 candidates (the module, login() which changes
        # every commit, and more() which is added at h2) are also already-
        # authoritative in any real system -- give each a legitimate
        # single-value authoritative :introduced-by fact too, rather than
        # leaving them with zero :introduced-by values.
        module_ident = mcp_server._code_ident("module", "auth.py")
        login_ident = mcp_server._code_ident("function", "auth.py", "login")
        more_ident = mcp_server._code_ident("function", "auth.py", "more")
        mcp_server._transact(real_db, f"[[{module_ident} :introduced-by :commit/{commit_metadata[0][0][:12]}]]", "2025-01-01T00:00:00Z")
        mcp_server._transact(real_db, f"[[{login_ident} :introduced-by :commit/{commit_metadata[0][0][:12]}]]", "2025-01-01T00:00:00Z")
        mcp_server._transact(real_db, f"[[{more_ident} :introduced-by {h2_ident}]]", "2025-01-01T00:00:00Z")

        file_results = self._extract(repo, h2_hash)
        precomputed_unchanged = [
            precomputed.get("unchanged_idents", set())
            for _status, _fp, _extracted, precomputed, _old in file_results
            if precomputed is not None
        ]
        assert any(extra_ident in u for u in precomputed_unchanged), (
            "fixture assumption broken: extra() must read as unchanged at h2"
        )

        skipped = mcp_server._correction_sweep_apply(real_db, h2_hash, h2_ts, file_results)

        assert skipped == 0
        # Bind the value and test membership. A query whose :find variable
        # appears nowhere in :where -- e.g.
        # [:find ?c :where [extra_ident :modified-in h2_ident]] -- binds ?c
        # to nothing and returns [] whether or not the fact exists, so
        # asserting == [] on that form passes even when the retract never
        # ran. The design spec calls this trap out for exactly this reason.
        raw = mcp_server._db_execute(
            real_db, f"(query [:find ?c :where [{extra_ident} :modified-in ?c]])"
        )
        modified_in_values = {row[0] for row in json.loads(raw)["results"]}
        assert h2_ident not in modified_in_values

    def test_skipped_events_counts_events_not_entities(self, real_db, tmp_path):
        import mcp_server
        repo = self._repo_with_evolving_function(tmp_path)
        commit_metadata = mcp_server._git_commits(str(repo), watermark_hash=None)
        h0_hash, h0_ts = commit_metadata[0][0], commit_metadata[0][1]
        h1_hash, h1_ts = commit_metadata[1][0], commit_metadata[1][1]
        fn_ident = mcp_server._code_ident("function", "auth.py", "login")
        wrong_ident = f":commit/{commit_metadata[2][0][:12]}"
        mcp_server._entity_introduced_by_set_provisional(real_db, fn_ident, wrong_ident, "2025-01-01T00:00:00Z")
        # auth.py's other candidates at h0/h1 (the module, and extra() which
        # is added at h1) are also already-authoritative in any real system
        # -- give each a legitimate single-value authoritative
        # :introduced-by fact once, up front, so they don't spuriously
        # count as skipped at either commit.
        module_ident = mcp_server._code_ident("module", "auth.py")
        extra_ident = mcp_server._code_ident("function", "auth.py", "extra")
        mcp_server._transact(real_db, f"[[{module_ident} :introduced-by :commit/{h0_hash[:12]}]]", "2025-01-01T00:00:00Z")
        mcp_server._transact(real_db, f"[[{extra_ident} :introduced-by :commit/{h1_hash[:12]}]]", "2025-01-01T00:00:00Z")

        skipped_h0 = mcp_server._correction_sweep_apply(real_db, h0_hash, h0_ts, self._extract(repo, h0_hash))
        skipped_h1 = mcp_server._correction_sweep_apply(
            real_db, h1_hash, h1_ts, self._extract(repo, h1_hash), skipped_so_far=skipped_h0,
        )

        assert skipped_h0 == 1
        assert skipped_h1 == 1  # login() is a candidate at h1 too -- second event, same entity

    def test_skip_logging_capped_with_returned_count_uncapped(self, real_db, tmp_path, capsys):
        import mcp_server
        repo = self._repo_with_evolving_function(tmp_path)
        commit_metadata = mcp_server._git_commits(str(repo), watermark_hash=None)
        h0_hash, h0_ts = commit_metadata[0][0], commit_metadata[0][1]
        # 15 synthetic candidate idents in one file entry, each provisional
        # with a guess pointing elsewhere -- avoids needing 15 real commits
        # to exercise the logging cap; precomputed's shape is documented in
        # this task's Interfaces block.
        n = 15
        idents = [f":function/synthetic-{i}" for i in range(n)]
        wrong_ident = ":commit/does-not-matter"
        for ident in idents:
            mcp_server._entity_introduced_by_set_provisional(real_db, ident, wrong_ident, "2025-01-01T00:00:00Z")
        # The synthetic module ident is also an unconditional candidate --
        # give it a legitimate single-value authoritative :introduced-by
        # fact too, so it doesn't spuriously count as a 16th skip.
        mcp_server._transact(real_db, "[[:module/synthetic :introduced-by :commit/preexisting]]", "2025-01-01T00:00:00Z")
        precomputed = {
            "module_ident": ":module/synthetic",
            "module_candidate_triples": [],
            "function_entries": [(ident, ident, []) for ident in idents],
            "class_entries": [],
            "global_entries": [],
            "field_entries": [],
            "unchanged_idents": set(),
        }
        file_results = [("M", "synthetic.py", {}, precomputed, "")]

        skipped = mcp_server._correction_sweep_apply(real_db, h0_hash, h0_ts, file_results)

        assert skipped == n
        err = capsys.readouterr().err
        logged_lines = [line for line in err.splitlines() if "synthetic-" in line]
        assert len(logged_lines) == mcp_server._CORRECTION_SWEEP_LOG_CAP

    def test_log_cap_is_caller_threaded_not_a_module_global(self, real_db, tmp_path, capsys):
        import mcp_server
        repo = self._repo_with_evolving_function(tmp_path)
        commit_metadata = mcp_server._git_commits(str(repo), watermark_hash=None)
        h0_hash, h0_ts = commit_metadata[0][0], commit_metadata[0][1]
        fn_ident = mcp_server._code_ident("function", "auth.py", "login")
        wrong_ident = f":commit/{commit_metadata[1][0][:12]}"
        mcp_server._entity_introduced_by_set_provisional(real_db, fn_ident, wrong_ident, "2025-01-01T00:00:00Z")
        file_results = self._extract(repo, h0_hash)

        capsys.readouterr()  # clear
        mcp_server._correction_sweep_apply(
            real_db, h0_hash, h0_ts, file_results, skipped_so_far=mcp_server._CORRECTION_SWEEP_LOG_CAP,
        )
        assert capsys.readouterr().err == ""  # budget already spent by caller's running total

        mcp_server._entity_introduced_by_set_provisional(real_db, fn_ident, wrong_ident, "2025-01-01T00:00:00Z")
        mcp_server._correction_sweep_apply(real_db, h0_hash, h0_ts, file_results, skipped_so_far=0)
        assert "login" in capsys.readouterr().err  # fresh run, budget reset

    def test_correction_sweep_log_summary(self, capsys):
        import mcp_server
        mcp_server._correction_sweep_log_summary(0)
        assert capsys.readouterr().err == ""

        mcp_server._correction_sweep_log_summary(3)
        err = capsys.readouterr().err
        assert err.strip() != ""
        assert "3" in err

    def test_case_one_re_dates_structural_facts(self, real_db, tmp_path):
        """#233: the sweep's confirm branch is where re-dating now happens.
        It already has the triples -- precomputed carries
        module_candidate_triples and (ident, name, triples) per entries key
        -- and previously read only the idents out of it."""
        import mcp_server
        import frontier_registry
        repo = tmp_path / "repo"
        repo.mkdir()
        _subprocess.run(["git", "init"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.email", "t@t.com"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.name", "T"], cwd=repo, check=True, capture_output=True)
        for i in range(3):
            if i > 0:
                time.sleep(1.1)  # ensure distinct commit-timestamp seconds; see git_repo_with_deletion
            (repo / "auth.py").write_text(f"def login():\n    return {i}\n")
            _subprocess.run(["git", "add", "."], cwd=repo, check=True, capture_output=True)
            _subprocess.run(["git", "commit", "-m", f"c{i}"], cwd=repo, check=True, capture_output=True)
        linearization = frontier_registry.build_linearization(str(repo))
        commit_metadata = mcp_server._git_commits(str(repo), watermark_hash=None)
        allocator = mcp_server._frontier_load(real_db, linearization, "2026-01-04T00:00:00Z")
        mcp_server._reverse_bulk_fill_walk(
            real_db, str(repo), linearization, commit_metadata, allocator,
        )
        login = mcp_server._code_ident("function", "auth.py", "login")

        file_results, _g, _m, _r = mcp_server._extract_commit(str(repo), linearization[0], ())
        mcp_server._correction_sweep_apply(
            real_db, linearization[0], commit_metadata[0][1], file_results,
        )

        assert mcp_server._lineage_is_provisional(real_db, login) is False
        raw = mcp_server._db_execute(
            real_db,
            f'(query [:find ?a :valid-at "{commit_metadata[0][1]}" :where [{login} ?a ?v]])',
        )
        attrs = {row[0] for row in json.loads(raw)["results"]}
        assert ":entity-type" in attrs
        assert ":file" in attrs

    def test_case_one_re_dates_the_contains_edge(self, real_db, tmp_path):
        """A child's own candidate triples carry its [parent :contains child]
        edge, so re-dating a child must re-date its containment edge with it:
        a re-dated child's containment edge must still be live (valid-at) at
        the child's introduction timestamp, for all three siblings. This is
        the edge minigraf#287 would destroy if the re-date ever batched
        multiple children of one module's :contains facts into a single
        _transact/_retract call.

        _re_date_structural_facts does split its triples one call per triple
        (#233), but at this call site that split is defensive rather than
        load-bearing: a child's own candidate-triples list carries exactly
        its own containment edge, and module_candidate_triples carries none,
        so _re_date_structural_facts is only ever handed 0 or 1 :contains
        triple per call here regardless of the split. The constraint the
        split guards against is real elsewhere (minigraf#287 / #222 phase
        2b1), just not exercised by this test."""
        import mcp_server
        import frontier_registry
        repo = tmp_path / "repo"
        repo.mkdir()
        _subprocess.run(["git", "init"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.email", "t@t.com"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.name", "T"], cwd=repo, check=True, capture_output=True)
        for i in range(3):
            if i > 0:
                time.sleep(1.1)  # ensure distinct commit-timestamp seconds; see git_repo_with_deletion
            (repo / "auth.py").write_text(
                f"def a():\n    return {i}\n\ndef b():\n    return {i}\n\ndef c():\n    return {i}\n"
            )
            _subprocess.run(["git", "add", "."], cwd=repo, check=True, capture_output=True)
            _subprocess.run(["git", "commit", "-m", f"c{i}"], cwd=repo, check=True, capture_output=True)
        linearization = frontier_registry.build_linearization(str(repo))
        commit_metadata = mcp_server._git_commits(str(repo), watermark_hash=None)
        allocator = mcp_server._frontier_load(real_db, linearization, "2026-01-04T00:00:00Z")
        mcp_server._reverse_bulk_fill_walk(
            real_db, str(repo), linearization, commit_metadata, allocator,
        )

        mcp_server._correction_sweep_walk(
            real_db, str(repo), linearization, commit_metadata,
        )

        module = mcp_server._code_ident("module", "auth.py")
        raw = mcp_server._db_execute(
            real_db,
            f'(query [:find ?child :valid-at "{commit_metadata[0][1]}" '
            f'  :where [{module} :contains ?child]])',
        )
        children = {row[0] for row in json.loads(raw)["results"]}
        assert len(children) == 3, f"all three containment edges must survive; got {sorted(children)}"

    def test_confirm_is_batched_across_entities_at_one_commit(self, real_db, tmp_path):
        """#233: _lineage_confirm was one retract per confirmed entity, and
        retracts are the expensive op. The markers are distinct :lineage/...
        companion entities, so one call covers them all."""
        import mcp_server
        import frontier_registry
        repo = tmp_path / "repo"
        repo.mkdir()
        _subprocess.run(["git", "init"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.email", "t@t.com"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.name", "T"], cwd=repo, check=True, capture_output=True)
        bodies = "\n\n".join(f"def f{i}():\n    return 0" for i in range(8))
        (repo / "wide.py").write_text(bodies + "\n")
        _subprocess.run(["git", "add", "."], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "commit", "-m", "c0"], cwd=repo, check=True, capture_output=True)
        linearization = frontier_registry.build_linearization(str(repo))
        commit_metadata = mcp_server._git_commits(str(repo), watermark_hash=None)
        allocator = mcp_server._frontier_load(real_db, linearization, "2026-01-04T00:00:00Z")
        mcp_server._reverse_bulk_fill_walk(
            real_db, str(repo), linearization, commit_metadata, allocator,
        )
        file_results, _g, _m, _r = mcp_server._extract_commit(str(repo), linearization[0], ())

        retracts = []
        real_retract = mcp_server._retract
        mcp_server._retract = lambda db_, facts, *a, **k: (
            retracts.append(facts) or real_retract(db_, facts, *a, **k)
        )
        try:
            mcp_server._correction_sweep_apply(
                real_db, linearization[0], commit_metadata[0][1], file_results,
            )
        finally:
            mcp_server._retract = real_retract

        marker_retracts = [f for f in retracts if ":type/lineage-marker" in f]
        assert len(marker_retracts) == 1, (
            f"one retract for every marker at this commit; got {len(marker_retracts)}"
        )
        for i in range(8):
            ident = mcp_server._code_ident("function", "wide.py", f"f{i}")
            assert mcp_server._lineage_is_provisional(real_db, ident) is False

    def _pos_map(self, repo):
        import mcp_server, frontier_registry
        linearization = frontier_registry.build_linearization(str(repo))
        return {f":commit/{h[:12]}": i for i, h in enumerate(linearization)}, linearization

    def test_repair_keeps_the_lowest_position_introduced_by(self, real_db, tmp_path):
        """#235: an entity carrying two live :introduced-by values is
        collapsed to the one at the LOWEST linearization position. The
        reverse stream's guess is a sighting at or above the true
        introduction -- the same direction its own monotonicity rule
        encodes -- so the earlier value is the introduction."""
        import mcp_server
        repo = self._repo_with_evolving_function(tmp_path)
        pos_map, linearization = self._pos_map(repo)
        h0, h2 = f":commit/{linearization[0][:12]}", f":commit/{linearization[2][:12]}"

        fn_ident = mcp_server._code_ident("function", "auth.py", "login")
        mcp_server._transact(real_db, f"[[{fn_ident} :introduced-by {h2}]]", "2026-01-03T00:00:00Z")
        mcp_server._transact(real_db, f"[[{fn_ident} :introduced-by {h0}]]", "2026-01-01T00:00:00Z")
        assert len(mcp_server._entity_introduced_by_values_query(real_db, fn_ident)) == 2

        # The sweep meets the entity at h1 -- NEITHER of its two values.
        # That is the real shape: the second mint happens in the forward
        # region, which Stage B never sweeps, so a rule keyed on "is this
        # commit one of the values" would never fire.
        h1_hash, h1_ts = linearization[1], "2026-01-02T00:00:00Z"
        mcp_server._correction_sweep_apply(
            real_db, h1_hash, h1_ts, self._extract(repo, h1_hash),
            pos_by_commit_ident=pos_map,
        )

        assert mcp_server._entity_introduced_by_values_query(real_db, fn_ident) == [h0]

    def test_repair_is_inert_without_a_position_map(self, real_db, tmp_path):
        """Gated: every existing caller and test keeps today's fail-safe
        behaviour until it opts in. An EMPTY map is gated out too -- with no
        positions to compare, every value scores the same len(map)==0
        default and the collapse would degenerate to "lexicographically
        smallest ident wins", contradicting "absent sorts last"."""
        import mcp_server
        repo = self._repo_with_evolving_function(tmp_path)
        _pos_map, linearization = self._pos_map(repo)
        h0, h2 = f":commit/{linearization[0][:12]}", f":commit/{linearization[2][:12]}"

        fn_ident = mcp_server._code_ident("function", "auth.py", "login")
        mcp_server._transact(real_db, f"[[{fn_ident} :introduced-by {h2}]]", "2026-01-03T00:00:00Z")
        mcp_server._transact(real_db, f"[[{fn_ident} :introduced-by {h0}]]", "2026-01-01T00:00:00Z")

        h1_hash = linearization[1]
        mcp_server._correction_sweep_apply(
            real_db, h1_hash, "2026-01-02T00:00:00Z", self._extract(repo, h1_hash),
        )

        assert sorted(mcp_server._entity_introduced_by_values_query(real_db, fn_ident)) == sorted([h0, h2])

        mcp_server._correction_sweep_apply(
            real_db, h1_hash, "2026-01-02T00:00:00Z", self._extract(repo, h1_hash),
            pos_by_commit_ident={},
        )

        assert sorted(mcp_server._entity_introduced_by_values_query(real_db, fn_ident)) == sorted([h0, h2])

    def test_repair_sorts_an_unknown_commit_ident_last(self, real_db, tmp_path):
        """A value absent from the map must never be chosen over a known
        one, and must never raise."""
        import mcp_server
        repo = self._repo_with_evolving_function(tmp_path)
        pos_map, linearization = self._pos_map(repo)
        h0 = f":commit/{linearization[0][:12]}"

        fn_ident = mcp_server._code_ident("function", "auth.py", "login")
        mcp_server._transact(real_db, f"[[{fn_ident} :introduced-by :commit/deadbeef0000]]", "2026-01-03T00:00:00Z")
        mcp_server._transact(real_db, f"[[{fn_ident} :introduced-by {h0}]]", "2026-01-01T00:00:00Z")

        h1_hash = linearization[1]
        mcp_server._correction_sweep_apply(
            real_db, h1_hash, "2026-01-02T00:00:00Z", self._extract(repo, h1_hash),
            pos_by_commit_ident=pos_map,
        )

        assert mcp_server._entity_introduced_by_values_query(real_db, fn_ident) == [h0]

    def test_repair_then_case_one_confirms_in_the_same_call(self, real_db, tmp_path):
        """Repair collapses multiplicity only. If the survivor equals the
        commit being swept and the entity is still provisional, case 1 runs
        on the repaired value and confirms it -- without repair it would
        have hit case 2's fail-safe skip."""
        import mcp_server, frontier_registry
        repo = self._repo_with_evolving_function(tmp_path)
        pos_map, linearization = self._pos_map(repo)
        h0, h2 = f":commit/{linearization[0][:12]}", f":commit/{linearization[2][:12]}"

        fn_ident = mcp_server._code_ident("function", "auth.py", "login")
        # The module is a candidate at h0 too. Seed it authoritative at h0 so
        # the returned skipped count speaks only about fn_ident: an unseeded
        # module has zero :introduced-by values and takes case 3's ambiguous
        # skip, which would mask whether repair-then-confirm skipped anything.
        mcp_server._transact(
            real_db,
            f"[[{mcp_server._code_ident('module', 'auth.py')} :introduced-by {h0}]]",
            "2026-01-01T00:00:00Z",
        )
        # Provisional at h0 (marker created), then a stray second value at h2.
        mcp_server._entity_introduced_by_set_provisional(real_db, fn_ident, h0, "2026-01-01T00:00:00Z")
        mcp_server._transact(real_db, f"[[{fn_ident} :introduced-by {h2}]]", "2026-01-03T00:00:00Z")
        assert mcp_server._lineage_is_provisional(real_db, fn_ident) is True

        h0_hash = linearization[0]
        skipped = mcp_server._correction_sweep_apply(
            real_db, h0_hash, "2026-01-01T00:00:00Z", self._extract(repo, h0_hash),
            pos_by_commit_ident=pos_map,
        )

        assert mcp_server._entity_introduced_by_values_query(real_db, fn_ident) == [h0]
        assert mcp_server._lineage_is_provisional(real_db, fn_ident) is False
        assert skipped == 0, "repaired then confirmed -- nothing left provisional"


class TestCorrectionSweepClaimAndProcess:
    def _init_repo(self, repo):
        _subprocess.run(["git", "init"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.email", "t@t.com"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.name", "T"], cwd=repo, check=True, capture_output=True)

    def _commit(self, repo, filename, content, msg):
        (repo / filename).write_text(content)
        _subprocess.run(["git", "add", "."], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "commit", "-m", msg], cwd=repo, check=True, capture_output=True)

    def _repo_with_n_commits(self, tmp_path, n):
        repo = tmp_path / "repo"
        repo.mkdir()
        self._init_repo(repo)
        for i in range(n):
            self._commit(repo, f"f{i}.py", f"def f{i}(): pass\n", f"h{i}")
        return repo

    def _linearization_and_metadata(self, repo):
        import mcp_server
        import frontier_registry
        linearization = frontier_registry.build_linearization(str(repo))
        commit_metadata = mcp_server._git_commits(str(repo), watermark_hash=None)
        return linearization, commit_metadata

    def _close_gap(self, repo, db, linearization, commit_metadata):
        """Claim exactly one position from the low side via a real
        FrontierAllocator + _frontier_persist_claim (standing in for 2d's
        future ordinary forward walk), then claim the rest from the high
        side via 2b's real _reverse_fill_claim_and_process until the gap is
        empty. Claiming the *whole* gap from the low side alone (an
        unbounded claim_low() loop) would never touch frontier-high at
        all -- claim_low() alone can empty the gap without claim_high()
        ever running, since gap_hi only moves when claim_high() does -- so
        the low side must stop after a bounded number of claims for
        frontier-high to end up populated. db here is any MiniGrafDb
        instance -- the real_db fixture in most tests, or a
        manually-created MiniGrafDb.open_in_memory() in the two-graph
        composition test below."""
        import mcp_server
        allocator = mcp_server._frontier_load(db, linearization, "2026-01-04T00:00:00Z")
        pos = allocator.claim_low()
        if pos is not None:
            mcp_server._frontier_persist_claim(
                db, linearization, pos, from_low=True, commit_ts_iso=commit_metadata[pos][1],
            )
        while not allocator.is_gap_empty():
            mcp_server._reverse_fill_claim_and_process(
                db, str(repo), linearization, commit_metadata, allocator,
            )
        return allocator

    def test_no_op_propagates_from_select_position(self, real_db, tmp_path):
        import mcp_server
        repo = self._repo_with_n_commits(tmp_path, 2)
        linearization, commit_metadata = self._linearization_and_metadata(repo)
        allocator = mcp_server._frontier_load(real_db, linearization, "2026-01-04T00:00:00Z")
        # Genuinely seed frontier-low, leaving frontier-high unclaimed.
        pos = allocator.claim_low()
        mcp_server._frontier_persist_claim(
            real_db, linearization, pos, from_low=True, commit_ts_iso=commit_metadata[pos][1],
        )

        result = mcp_server._correction_sweep_claim_and_process(
            real_db, str(repo), linearization, commit_metadata,
        )
        assert result is None

    def test_single_call_round_trip(self, real_db, tmp_path):
        import mcp_server
        repo = self._repo_with_n_commits(tmp_path, 3)
        linearization, commit_metadata = self._linearization_and_metadata(repo)
        self._close_gap(repo, real_db, linearization, commit_metadata)

        result = mcp_server._correction_sweep_claim_and_process(
            real_db, str(repo), linearization, commit_metadata,
        )
        assert result is not None
        commit_hash, skipped_events = result
        bounds = mcp_server._frontier_read_bounds(real_db, mcp_server._FRONTIER_HIGH_IDENT)
        assert commit_hash == bounds[0]
        assert skipped_events == 0
        assert mcp_server._correction_sweep_through_query(real_db) == commit_hash

    def test_wrapper_is_a_faithful_composition_of_the_three_pieces(self, tmp_path):
        """Build TWO independent graphs from the same repo fixture (the
        sweep mutates the state a second run would start from, so this
        cannot be two passes over one graph). Against the first, call the
        wrapper; against the second, call the three pieces directly.
        Assert the resulting graph states are identical. Both dbs are
        passed explicitly to every call -- none of these functions touch
        mcp_server's module-global _db -- so this test needs no real_db
        fixture and no open_db() call, just two independent
        MiniGrafDb.open_in_memory() instances."""
        import mcp_server
        from minigraf import MiniGrafDb
        repo = self._repo_with_n_commits(tmp_path, 3)
        linearization, commit_metadata = self._linearization_and_metadata(repo)

        db_a = MiniGrafDb.open_in_memory()
        self._close_gap(repo, db_a, linearization, commit_metadata)
        mcp_server._correction_sweep_claim_and_process(db_a, str(repo), linearization, commit_metadata)

        db_b = MiniGrafDb.open_in_memory()
        self._close_gap(repo, db_b, linearization, commit_metadata)
        selected = mcp_server._correction_sweep_select_position(db_b, linearization, commit_metadata)
        assert selected is not None
        commit_hash, commit_ts_iso = selected
        file_results, _, _, _ = mcp_server._extract_commit(str(repo), commit_hash, ())
        mcp_server._correction_sweep_apply(db_b, commit_hash, commit_ts_iso, file_results)

        query = "(query [:find ?e ?a ?v :where [?e ?a ?v]])"
        results_a = sorted(json.loads(db_a.execute(query))["results"])
        results_b = sorted(json.loads(db_b.execute(query))["results"])
        assert results_a == results_b


class TestCorrectionSweepWalk:
    def _init_repo(self, repo):
        _subprocess.run(["git", "init"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.email", "t@t.com"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.name", "T"], cwd=repo, check=True, capture_output=True)

    def _commit(self, repo, filename, content, msg):
        (repo / filename).write_text(content)
        _subprocess.run(["git", "add", "."], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "commit", "-m", msg], cwd=repo, check=True, capture_output=True)

    def _repo_with_n_commits(self, tmp_path, n):
        repo = tmp_path / "repo"
        repo.mkdir()
        self._init_repo(repo)
        for i in range(n):
            self._commit(repo, f"f{i}.py", f"def f{i}(): pass\n", f"h{i}")
        return repo

    def _linearization_and_metadata(self, repo):
        import mcp_server
        import frontier_registry
        linearization = frontier_registry.build_linearization(str(repo))
        commit_metadata = mcp_server._git_commits(str(repo), watermark_hash=None)
        return linearization, commit_metadata

    def _close_gap_at(self, repo, real_db, linearization, commit_metadata, split_pos):
        """Close the gap with the low side claiming positions [0, split_pos)
        and the high side (2b) claiming the rest -- split_pos == len(linearization)
        closes the whole thing from the low side alone."""
        import mcp_server
        allocator = mcp_server._frontier_load(real_db, linearization, "2026-01-04T00:00:00Z")
        for _ in range(split_pos):
            pos = allocator.claim_low()
            mcp_server._frontier_persist_claim(
                real_db, linearization, pos, from_low=True, commit_ts_iso=commit_metadata[pos][1],
            )
        while not allocator.is_gap_empty():
            mcp_server._reverse_fill_claim_and_process(
                real_db, str(repo), linearization, commit_metadata, allocator,
            )
        return allocator

    def test_walks_to_exhaustion_and_returns_counts(self, real_db, tmp_path):
        import mcp_server
        repo = self._repo_with_n_commits(tmp_path, 4)
        linearization, commit_metadata = self._linearization_and_metadata(repo)
        self._close_gap_at(repo, real_db, linearization, commit_metadata, split_pos=1)

        commits_processed, skipped_events = mcp_server._correction_sweep_walk(
            real_db, str(repo), linearization, commit_metadata,
        )

        assert commits_processed == 3
        assert skipped_events == 0
        assert mcp_server._correction_sweep_through_query(real_db) == linearization[-1]

    def _repo_with_one_evolving_file(self, tmp_path, n):
        """n commits all touching a.py, so its entities are candidates at
        every swept commit -- _repo_with_n_commits gives each commit its own
        file, which the sweep only ever sees once."""
        repo = tmp_path / "repo"
        repo.mkdir()
        self._init_repo(repo)
        for i in range(n):
            self._commit(repo, "a.py", f"def login():\n    return {i}\n", f"h{i}")
        return repo

    def test_walk_arms_the_two_value_repair(self, real_db, tmp_path):
        """#235: _correction_sweep_apply's repair is inert unless a caller
        supplies pos_by_commit_ident, and _correction_sweep_walk is the
        driving loop that has commit_metadata in scope. If it does not build
        and pass the map, an entity holding two live :introduced-by values
        is merely logged as ambiguous and survives the whole sweep."""
        import mcp_server
        repo = self._repo_with_one_evolving_file(tmp_path, 3)
        linearization, commit_metadata = self._linearization_and_metadata(repo)
        self._close_gap_at(repo, real_db, linearization, commit_metadata, split_pos=1)

        fn_ident = mcp_server._code_ident("function", "a.py", "login")
        h0 = f":commit/{linearization[0][:12]}"
        h2 = f":commit/{linearization[2][:12]}"
        # Force exactly the corruption the old _forward_apply produced: a
        # second live value alongside whatever the reverse stream recorded.
        for value in (h0, h2):
            if value not in mcp_server._entity_introduced_by_values_query(real_db, fn_ident):
                mcp_server._transact(
                    real_db, f"[[{fn_ident} :introduced-by {value}]]", "2026-01-01T00:00:00Z",
                )
        before = mcp_server._entity_introduced_by_values_query(real_db, fn_ident)
        assert len(before) >= 2, f"fixture must start corrupt; got {before}"

        mcp_server._correction_sweep_walk(real_db, str(repo), linearization, commit_metadata)

        after = mcp_server._entity_introduced_by_values_query(real_db, fn_ident)
        assert after == [h0], (
            f"the walk must collapse to the lowest-position value; got {sorted(after)}"
        )

    def test_returns_zero_zero_when_gap_still_open(self, real_db, tmp_path):
        import mcp_server
        repo = self._repo_with_n_commits(tmp_path, 3)
        linearization, commit_metadata = self._linearization_and_metadata(repo)
        allocator = mcp_server._frontier_load(real_db, linearization, "2026-01-04T00:00:00Z")
        mcp_server._reverse_fill_claim_and_process(
            real_db, str(repo), linearization, commit_metadata, allocator,
        )
        assert allocator.is_gap_empty() is False

        result = mcp_server._correction_sweep_walk(real_db, str(repo), linearization, commit_metadata)
        assert result == (0, 0)

    def test_no_op_when_already_fully_swept(self, real_db, tmp_path):
        import mcp_server
        repo = self._repo_with_n_commits(tmp_path, 2)
        linearization, commit_metadata = self._linearization_and_metadata(repo)
        self._close_gap_at(repo, real_db, linearization, commit_metadata, split_pos=1)
        mcp_server._correction_sweep_walk(real_db, str(repo), linearization, commit_metadata)

        result = mcp_server._correction_sweep_walk(real_db, str(repo), linearization, commit_metadata)
        assert result == (0, 0)

    def test_frontier_low_and_lineage_confirmed_through_never_touched(self, real_db, tmp_path):
        import mcp_server
        repo = self._repo_with_n_commits(tmp_path, 3)
        linearization, commit_metadata = self._linearization_and_metadata(repo)
        self._close_gap_at(repo, real_db, linearization, commit_metadata, split_pos=1)

        low_before = mcp_server._frontier_read_bounds(real_db, mcp_server._FRONTIER_LOW_IDENT)
        lineage_before = mcp_server._lineage_confirmed_through_query(real_db)

        mcp_server._correction_sweep_walk(real_db, str(repo), linearization, commit_metadata)

        low_after = mcp_server._frontier_read_bounds(real_db, mcp_server._FRONTIER_LOW_IDENT)
        lineage_after = mcp_server._lineage_confirmed_through_query(real_db)
        assert low_after == low_before
        assert lineage_after == lineage_before
        assert mcp_server._correction_sweep_through_query(real_db) is not None

    def test_full_integration(self, real_db, tmp_path):
        import mcp_server
        repo = self._repo_with_n_commits(tmp_path, 5)
        linearization, commit_metadata = self._linearization_and_metadata(repo)
        self._close_gap_at(repo, real_db, linearization, commit_metadata, split_pos=2)

        commits_processed, skipped_events = mcp_server._correction_sweep_walk(
            real_db, str(repo), linearization, commit_metadata,
        )

        assert commits_processed == 3  # the 3 positions the high side claimed
        assert skipped_events == 0
        for i in range(5):
            fn_ident = mcp_server._code_ident("function", f"f{i}.py", f"f{i}")
            assert mcp_server._lineage_is_provisional(real_db, fn_ident) is False
        bounds = mcp_server._frontier_read_bounds(real_db, mcp_server._FRONTIER_HIGH_IDENT)
        assert mcp_server._correction_sweep_through_query(real_db) == bounds[1]


class TestParseStreamRatio:
    def test_default_when_unset(self):
        import mcp_server
        assert mcp_server._parse_stream_ratio(None) == (1, 1)

    def test_parses_explicit_ratios(self):
        import mcp_server
        assert mcp_server._parse_stream_ratio("1:1") == (1, 1)
        assert mcp_server._parse_stream_ratio("1:3") == (1, 3)
        assert mcp_server._parse_stream_ratio("3:1") == (3, 1)
        assert mcp_server._parse_stream_ratio(" 2 : 5 ") == (2, 5)

    def test_malformed_falls_back_to_default_and_logs_once(self, capsys):
        import mcp_server
        for bad in ("x", "", "1", "1:2:3", "0:1", "1:0", "-1:2", "a:b", "1.5:2"):
            assert mcp_server._parse_stream_ratio(bad) == (1, 1), bad
        err = capsys.readouterr().err
        # One line per bad value, and each names the offending value.
        assert err.count("MINIGRAF_INGEST_STREAM_RATIO") == 9

    def test_does_not_raise_on_any_input(self):
        """A bad env var must never be the reason a repo never ingests --
        this runs inside a background coroutine with no user in the loop."""
        import mcp_server
        assert mcp_server._parse_stream_ratio("\x00\xff") == (1, 1)


class TestReDateStructuralFactsKeepsEverySiblingEdge:
    """#284 item 6 / minigraf#287: the per-triple split in
    _re_date_structural_facts is load-bearing and was UNGUARDED.

    minigraf#287 is still OPEN and reproduces identically on 1.2.3 and 2.0.0:
    facts sharing (entity, attribute, valid_from) in ONE transact collapse to
    the last, because the EAVT pending index omits value bytes. This repo's
    only protection is transacting such facts one per call, and we now depend
    on that indefinitely -- upstream has no fix in either version.

    The pre-existing test_contains_edge_survives_re_dating asserts a SINGLE
    surviving edge, so it cannot see the collision: with one edge there is
    nothing to collide with, and it passes with the split removed. Ablation
    confirmed the whole suite passed with :contains batched back in here,
    which left this site one plausible "merge these two loops" edit away from
    silently losing containment edges -- the exact #222 phase 2b1 bug that
    cost five of six edges on an ordinary multi-entity file, permanently.

    Two siblings is the minimum that can collide, so this uses three.
    """

    def test_every_sibling_contains_edge_survives_re_dating(self, real_db):
        import mcp_server

        old_ts, new_ts = "2026-06-01T00:00:00Z", "2026-01-01T00:00:00Z"
        children = [":code/fn-a", ":code/fn-b", ":code/fn-c"]
        structural = [f"[:module/auth :contains {c}]" for c in children]

        # Seed one per call, so the SEEDING cannot itself be the thing that
        # loses edges -- otherwise a failure below would be ambiguous.
        for triple in structural:
            mcp_server._transact(real_db, f"[{triple}]", old_ts)

        # Positive control: all three are really present before re-dating.
        raw = mcp_server._db_execute(
            real_db,
            f'(query [:find ?c :valid-at "{old_ts}" '
            ':where [:module/auth :contains ?c]])',
        )
        assert sorted(r[0] for r in json.loads(raw)["results"]) == sorted(children)

        mcp_server._re_date_structural_facts(real_db, structural, new_ts)

        raw = mcp_server._db_execute(
            real_db,
            f'(query [:find ?c :valid-at "{new_ts}" '
            ':where [:module/auth :contains ?c]])',
        )
        survived = sorted(r[0] for r in json.loads(raw)["results"])
        assert survived == sorted(children), (
            "re-dating lost sibling :contains edges -- they were batched into "
            f"one transact and collapsed (minigraf#287). Survived: {survived}"
        )


class TestForwardStructuralTriplesByIdent:
    """`_forward_structural_triples_by_ident` had no direct unit test -- it
    was only ever exercised through _forward_apply and the correction sweep,
    both of which would keep passing if it silently returned fewer idents."""

    def test_every_candidate_ident_gets_an_entry(self):
        """The two functions read the SAME five sources and must agree about
        which idents exist. _forward_apply asserts on exactly this
        correspondence (mcp_server.py:11989), so a silent disagreement shows
        up there as a hard failure mid-ingestion rather than here."""
        import mcp_server
        # The third element of each *_entries tuple is that entity's own
        # TRIPLE LIST -- not a type string. _forward_candidate_idents unpacks
        # it as `for ident, _name, _t in ...` and discards it; this function
        # is the consumer that actually uses it.
        precomputed = {
            "module_ident": ":module/auth-py",
            "module_candidate_triples": [
                "[:module/auth-py :entity-type :type/module]",
                '[:module/auth-py :path "auth.py"]',
            ],
            "function_entries": [(
                ":function/auth-py-login", "login",
                ["[:function/auth-py-login :entity-type :type/function]",
                 "[:module/auth-py :contains :function/auth-py-login]"],
            )],
            "class_entries": [(
                ":class/auth-py-user", "User",
                ["[:class/auth-py-user :entity-type :type/class]"],
            )],
            "global_entries": [(
                ":variable/auth-py-limit", "LIMIT",
                ["[:variable/auth-py-limit :entity-type :type/variable]"],
            )],
            "field_entries": [(
                ":field/auth-py-user-name", "name",
                ["[:field/auth-py-user-name :entity-type :type/field]"],
            )],
        }
        result = mcp_server._forward_structural_triples_by_ident(precomputed)
        for ident in mcp_server._forward_candidate_idents(precomputed):
            assert ident in result, (
                f"{ident} is a candidate ident but has no structural triples; "
                f"_forward_apply asserts on exactly this correspondence"
            )
            assert result[ident], f"{ident} mapped to an empty triple list"

    def test_a_child_carries_its_own_containment_edge(self):
        """#222 phase 2b1: a child's list carries its [parent :contains child]
        edge, so re-dating the child re-dates the containment with it. Pinned
        because nothing else asserts it directly."""
        import mcp_server
        precomputed = {
            "module_ident": ":module/auth-py",
            "module_candidate_triples": ["[:module/auth-py :entity-type :type/module]"],
            "function_entries": [(
                ":function/auth-py-login", "login",
                ["[:function/auth-py-login :entity-type :type/function]",
                 "[:module/auth-py :contains :function/auth-py-login]"],
            )],
            "class_entries": [], "global_entries": [], "field_entries": [],
        }
        result = mcp_server._forward_structural_triples_by_ident(precomputed)
        assert any(
            ":contains" in t for t in result[":function/auth-py-login"]
        ), "the child's own triple list lost its containment edge"


class TestForwardReconcileProvisional:
    # The commit the forward walk is currently applying, i.e. the entity's
    # TRUE introduction. Distinct from _seed_provisional's guess commit in
    # every test here except the self-introduction one below, which is the
    # whole point of that case (#222 phase 2d review, B2).
    _TRUE_COMMIT = ":commit/aaaaaaaaaaaa"

    def _seed_provisional(self, real_db):
        """An entity Stream 2 discovered at a late commit and guessed wrong."""
        import mcp_server
        guess_ident = ":commit/bbbbbbbbbbbb"
        structural = [
            ":code/fn-login :entity-type :type/function",
            ':code/fn-login :name "login"',
            ":module/auth :contains :code/fn-login",
        ]
        structural_triples = [f"[{t}]" for t in structural]
        mcp_server._transact(
            real_db, "[" + " ".join(f"[{t}]" for t in structural if ":contains" not in t) + "]",
            "2026-06-01T00:00:00Z",
        )
        mcp_server._transact(
            real_db, "[[:module/auth :contains :code/fn-login]]", "2026-06-01T00:00:00Z",
        )
        mcp_server._transact(
            real_db, f"[[:code/fn-login :introduced-by {guess_ident}]]", "2026-06-01T00:00:00Z",
        )
        mcp_server._lineage_mark_provisional(real_db, ":code/fn-login", "2026-06-01T00:00:00Z")
        return guess_ident, structural_triples

    def test_returns_none_and_writes_nothing_when_not_provisional(self, real_db):
        import mcp_server
        mcp_server._transact(
            real_db, "[[:code/fn-x :introduced-by :commit/aaaaaaaaaaaa]]", "2026-01-01T00:00:00Z",
        )
        result = mcp_server._forward_reconcile_provisional(
            real_db, ":code/fn-x", [], "2026-01-01T00:00:00Z", {}, self._TRUE_COMMIT,
        )
        assert result is None
        assert mcp_server._entity_introduced_by_query(real_db, ":code/fn-x") == ":commit/aaaaaaaaaaaa"

    def test_retracts_the_provisional_guess(self, real_db):
        import mcp_server
        guess_ident, structural = self._seed_provisional(real_db)
        mcp_server._forward_reconcile_provisional(
            real_db, ":code/fn-login", structural, "2026-01-01T00:00:00Z",
            {guess_ident: "2026-06-01T00:00:00Z"}, self._TRUE_COMMIT,
        )
        # No :introduced-by left at all -- the caller writes the authoritative
        # one immediately after, via the normal forward emission path.
        assert mcp_server._entity_introduced_by_query(real_db, ":code/fn-login") is None

    def test_confirms_the_marker(self, real_db):
        import mcp_server
        guess_ident, structural = self._seed_provisional(real_db)
        returned = mcp_server._forward_reconcile_provisional(
            real_db, ":code/fn-login", structural, "2026-01-01T00:00:00Z",
            {guess_ident: "2026-06-01T00:00:00Z"}, self._TRUE_COMMIT,
        )
        assert returned == guess_ident
        assert mcp_server._lineage_is_provisional(real_db, ":code/fn-login") is False

    def test_writes_modified_in_at_the_guess_commits_own_timestamp(self, real_db):
        """The guess commit is now known to be a genuine modification rather
        than the introduction. Dating the edge at the TRUE introduction's
        timestamp would assert a fact valid before it was true."""
        import mcp_server
        guess_ident, structural = self._seed_provisional(real_db)
        mcp_server._forward_reconcile_provisional(
            real_db, ":code/fn-login", structural, "2026-01-01T00:00:00Z",
            {guess_ident: "2026-06-01T00:00:00Z"}, self._TRUE_COMMIT,
        )
        raw = mcp_server._db_execute(
            real_db,
            '(query [:find ?c :valid-at "2026-06-02T00:00:00Z" '
            ':where [:code/fn-login :modified-in ?c]])',
        )
        assert [row[0] for row in json.loads(raw)["results"]] == [guess_ident]
        # Not yet true the day BEFORE the guess commit.
        raw_before = mcp_server._db_execute(
            real_db,
            '(query [:find ?c :valid-at "2026-05-31T00:00:00Z" '
            ':where [:code/fn-login :modified-in ?c]])',
        )
        assert json.loads(raw_before)["results"] == []

    def test_re_dates_structural_facts_to_the_true_introduction(self, real_db):
        """Otherwise there is a valid-time window where :introduced-by is live
        for an entity with no type, name or file, so an :as-of query at the
        true introduction reports the entity as nonexistent."""
        import mcp_server
        guess_ident, structural = self._seed_provisional(real_db)
        mcp_server._forward_reconcile_provisional(
            real_db, ":code/fn-login", structural, "2026-01-01T00:00:00Z",
            {guess_ident: "2026-06-01T00:00:00Z"}, self._TRUE_COMMIT,
        )
        raw = mcp_server._db_execute(
            real_db,
            '(query [:find ?n :valid-at "2026-02-01T00:00:00Z" '
            ':where [:code/fn-login :name ?n]])',
        )
        assert [row[0] for row in json.loads(raw)["results"]] == ["login"]

    def test_contains_edge_survives_re_dating(self, real_db):
        """:contains shares (entity, attribute, valid_from) with any sibling
        edge, so it must be retracted and re-transacted one triple per call
        -- batching silently keeps only the last (#222 phase 2b1)."""
        import mcp_server
        guess_ident, structural = self._seed_provisional(real_db)
        mcp_server._forward_reconcile_provisional(
            real_db, ":code/fn-login", structural, "2026-01-01T00:00:00Z",
            {guess_ident: "2026-06-01T00:00:00Z"}, self._TRUE_COMMIT,
        )
        raw = mcp_server._db_execute(
            real_db,
            '(query [:find ?c :valid-at "2026-02-01T00:00:00Z" '
            ':where [:module/auth :contains ?c]])',
        )
        assert [row[0] for row in json.loads(raw)["results"]] == [":code/fn-login"]

    def test_skips_modified_in_when_guess_timestamp_unknown(self, real_db, capsys):
        """Falling back to the true introduction's timestamp would back-date
        the edge to before the modification it describes. Skip and say so."""
        import mcp_server
        guess_ident, structural = self._seed_provisional(real_db)
        mcp_server._forward_reconcile_provisional(
            real_db, ":code/fn-login", structural, "2026-01-01T00:00:00Z", {},
            self._TRUE_COMMIT,
        )
        raw = mcp_server._db_execute(
            real_db, "(query [:find ?c :where [:code/fn-login :modified-in ?c]])",
        )
        assert json.loads(raw)["results"] == []
        assert "no timestamp in commit_metadata" in capsys.readouterr().err
        # The rest of the reconciliation still happened.
        assert mcp_server._lineage_is_provisional(real_db, ":code/fn-login") is False

    def test_skips_modified_in_when_the_guess_is_this_very_commit(self, real_db):
        """#222 phase 2d review, B2: Stream 2 claims high-to-low, so the first
        commit at which it sights an entity born inside its own region IS that
        entity's introduction -- a correct guess that still carries a
        provisional marker. When a later run's forward walk re-walks that
        position it must not "promote" the guess to a modification: the entity
        would end up :introduced-by and :modified-in the SAME commit, a shape
        forward-only ingest never produces and _correction_sweep_apply
        explicitly refuses to write."""
        import mcp_server
        guess_ident, structural = self._seed_provisional(real_db)
        returned = mcp_server._forward_reconcile_provisional(
            real_db, ":code/fn-login", structural, "2026-06-01T00:00:00Z",
            {guess_ident: "2026-06-01T00:00:00Z"}, guess_ident,
        )
        # Everything else still happens -- only step 5 is withheld.
        assert returned == guess_ident
        assert mcp_server._lineage_is_provisional(real_db, ":code/fn-login") is False
        assert mcp_server._entity_introduced_by_query(real_db, ":code/fn-login") is None
        raw = mcp_server._db_execute(
            real_db,
            '(query [:find ?c :any-valid-time '
            ':where [:code/fn-login :modified-in ?c]])',
        )
        assert json.loads(raw)["results"] == [], (
            "the entity was handed a :modified-in edge at its own introduction"
        )


class TestForwardApplyReconcilesProvisional:
    def _repo(self, tmp_path):
        repo = tmp_path / "repo"
        repo.mkdir()
        _subprocess.run(["git", "init"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.email", "t@t.com"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.name", "T"], cwd=repo, check=True, capture_output=True)
        (repo / "auth.py").write_text("def login():\n    return 1\n")
        _subprocess.run(["git", "add", "."], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "commit", "-m", "h0"], cwd=repo, check=True, capture_output=True)
        (repo / "auth.py").write_text("def login():\n    return 2\n")
        _subprocess.run(["git", "add", "."], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "commit", "-m", "h1"], cwd=repo, check=True, capture_output=True)
        return repo

    def test_forward_apply_supersedes_a_provisional_guess(self, real_db, tmp_path):
        """Stream 2 claimed h1 and guessed login() was introduced there. The
        forward walk then reaches h0, the TRUE introduction. Exactly one
        :introduced-by must survive, naming h0, with a confirmed marker."""
        import mcp_server, frontier_registry
        repo = self._repo(tmp_path)
        linearization = frontier_registry.build_linearization(str(repo))
        commit_metadata = mcp_server._git_commits(str(repo), watermark_hash=None)
        allocator = mcp_server._frontier_load(real_db, linearization, "2026-01-04T00:00:00Z")

        # Stream 2 claims the newest commit (h1) and guesses.
        mcp_server._reverse_fill_claim_and_process(
            real_db, str(repo), linearization, commit_metadata, allocator,
        )
        fn_ident = mcp_server._code_ident("function", "auth.py", "login")
        assert mcp_server._lineage_is_provisional(real_db, fn_ident) is True
        assert mcp_server._entity_introduced_by_query(real_db, fn_ident) == f":commit/{linearization[1][:12]}"

        # Stream 1 now reaches h0, the true introduction.
        state = mcp_server._ForwardWalkState(
            entity_valid_from={}, entity_descriptions={}, file_entities={},
            file_deps={}, dep_valid_from={}, pinned_commit_state={},
            field_class_ident={}, field_static_ident={}, submodule_paths={},
            unresolved_dep_idents={},
            # #235: no provisional-ident snapshot is threaded at all -- the
            # walk asks _lineage_is_provisional per ident. An earlier revision
            # of this test seeded one from _preload_provisional_idents AFTER
            # the reverse stream ran, which no real fresh run ever has, and
            # that hid the second-mint bug entirely.
            ts_by_commit_ident={f":commit/{h[:12]}": ts for h, ts, _a, _s in commit_metadata},
        )
        extracted = mcp_server._extract_commit(str(repo), linearization[0], ())
        mcp_server._forward_apply(
            real_db, str(repo), state, commit_metadata[0], extracted,
        )

        raw = mcp_server._db_execute(
            real_db, f"(query [:find ?c :where [{fn_ident} :introduced-by ?c]])",
        )
        values = {row[0] for row in json.loads(raw)["results"]}
        assert values == {f":commit/{linearization[0][:12]}"}, "exactly one, naming h0"
        assert mcp_server._lineage_is_provisional(real_db, fn_ident) is False
        # h1 is now a genuine modification.
        raw_mod = mcp_server._db_execute(
            real_db, f"(query [:find ?c :where [{fn_ident} :modified-in ?c]])",
        )
        assert f":commit/{linearization[1][:12]}" in {row[0] for row in json.loads(raw_mod)["results"]}

        # The module ident is provisional too (Stream 2 guessed it at h1
        # alongside login()) and exercises the distinct module-ident branch
        # of the reconciliation block/lookup -- not just the function-entry
        # branch. Same exactly-one-survivor, same confirmed marker.
        module_ident = mcp_server._code_ident("module", "auth.py")
        raw_module = mcp_server._db_execute(
            real_db, f"(query [:find ?c :where [{module_ident} :introduced-by ?c]])",
        )
        module_values = {row[0] for row in json.loads(raw_module)["results"]}
        assert module_values == {f":commit/{linearization[0][:12]}"}, "exactly one, naming h0"
        assert mcp_server._lineage_is_provisional(real_db, module_ident) is False

    def test_forward_apply_does_not_duplicate_for_an_already_confirmed_entity(
        self, real_db, tmp_path,
    ):
        """FIX 1 regression (#222 phase 2d Task 5 review, kept live by #235):
        an entity the reverse stream introduced provisionally and something
        else (e.g. the correction sweep) has since confirmed authoritative
        must NOT be treated as reconcilable. Popping it out of
        entity_valid_from unconditionally would make _build_code_triples mint
        a SECOND :introduced-by on top of the existing authoritative one,
        while _forward_reconcile_provisional (itself DB-backed) no-ops on an
        already-confirmed entity and never retracts the duplicate. Without
        the per-ident _lineage_is_provisional check this yields two
        :introduced-by values; with it, exactly one survives.

        This is the stale-POSITIVE half of the argument in _forward_apply's
        reconciliation comment: it is why the DB check cannot simply be
        dropped in favour of any set, snapshot or otherwise."""
        import mcp_server, frontier_registry
        repo = self._repo(tmp_path)
        linearization = frontier_registry.build_linearization(str(repo))
        commit_metadata = mcp_server._git_commits(str(repo), watermark_hash=None)
        allocator = mcp_server._frontier_load(real_db, linearization, "2026-01-04T00:00:00Z")

        # Stream 2 claims h1 and guesses login() was introduced there.
        mcp_server._reverse_fill_claim_and_process(
            real_db, str(repo), linearization, commit_metadata, allocator,
        )
        fn_ident = mcp_server._code_ident("function", "auth.py", "login")
        assert mcp_server._lineage_is_provisional(real_db, fn_ident) is True

        # Simulate something else confirming it authoritative in the DB
        # before the forward walk arrives (the existing :introduced-by fact
        # itself is untouched by that confirmation).
        mcp_server._lineage_confirm(real_db, fn_ident)
        assert mcp_server._lineage_is_provisional(real_db, fn_ident) is False
        existing_raw = mcp_server._db_execute(
            real_db, f"(query [:find ?c :where [{fn_ident} :introduced-by ?c]])",
        )
        assert {row[0] for row in json.loads(existing_raw)["results"]} == {
            f":commit/{linearization[1][:12]}"
        }

        # entity_valid_from already knows this entity (mirrors the resumed-run
        # shape) so an unconditional pop would matter.
        state = mcp_server._ForwardWalkState(
            entity_valid_from={fn_ident: "2026-06-01T00:00:00Z"},
            entity_descriptions={fn_ident: "login"}, file_entities={"auth.py": [fn_ident]},
            file_deps={}, dep_valid_from={}, pinned_commit_state={},
            field_class_ident={}, field_static_ident={}, submodule_paths={},
            unresolved_dep_idents={},
            ts_by_commit_ident={f":commit/{h[:12]}": ts for h, ts, _a, _s in commit_metadata},
        )
        extracted = mcp_server._extract_commit(str(repo), linearization[0], ())
        mcp_server._forward_apply(
            real_db, str(repo), state, commit_metadata[0], extracted,
        )

        raw = mcp_server._db_execute(
            real_db, f"(query [:find ?c :where [{fn_ident} :introduced-by ?c]])",
        )
        values = {row[0] for row in json.loads(raw)["results"]}
        assert values == {f":commit/{linearization[1][:12]}"}, (
            "exactly one :introduced-by must survive -- an already-confirmed "
            "entity must not have a second one minted on top of it"
        )

    def test_reconciles_a_guess_made_during_this_same_run(self, real_db, tmp_path):
        """#235: the prefilter was a run-start snapshot, empty on a fresh
        ingest. Stream 2's guesses are written during that same run, so the
        prefilter dropped every one of them before the DB-authoritative
        _lineage_is_provisional check could see it -- and
        _build_code_triples then minted a SECOND :introduced-by alongside
        the guess. The DB must be the sole authority."""
        import mcp_server, frontier_registry
        repo = self._repo(tmp_path)
        linearization = frontier_registry.build_linearization(str(repo))
        commit_metadata = mcp_server._git_commits(str(repo), watermark_hash=None)
        allocator = mcp_server._frontier_load(real_db, linearization, "2026-01-04T00:00:00Z")

        # The graph the forward walk starts against, exactly as _run_ingestion
        # sees it: nothing is provisional yet.
        assert mcp_server._preload_provisional_idents(real_db) == set(), (
            "a fresh graph has no provisional idents yet"
        )

        # Only now does Stream 2 claim h1 and guess.
        mcp_server._reverse_fill_claim_and_process(
            real_db, str(repo), linearization, commit_metadata, allocator,
        )
        fn_ident = mcp_server._code_ident("function", "auth.py", "login")
        assert mcp_server._lineage_is_provisional(real_db, fn_ident) is True

        state = mcp_server._ForwardWalkState(
            entity_valid_from={}, entity_descriptions={}, file_entities={},
            file_deps={}, dep_valid_from={}, pinned_commit_state={},
            field_class_ident={}, field_static_ident={}, submodule_paths={},
            unresolved_dep_idents={},
            ts_by_commit_ident={f":commit/{h[:12]}": ts for h, ts, _a, _s in commit_metadata},
        )
        extracted = mcp_server._extract_commit(str(repo), linearization[0], ())
        mcp_server._forward_apply(real_db, str(repo), state, commit_metadata[0], extracted)

        values = mcp_server._entity_introduced_by_values_query(real_db, fn_ident)
        assert values == [f":commit/{linearization[0][:12]}"], (
            f"exactly one :introduced-by, naming h0; got {sorted(values)}"
        )
        assert mcp_server._lineage_is_provisional(real_db, fn_ident) is False

    def test_resumed_run_variant_is_not_suppressed_by_entity_valid_from(self, real_db, tmp_path):
        """The silent failure mode: on a RESUMED run, Stream 2's structural
        facts are already in the preloaded entity_valid_from, so
        _build_code_triples would suppress the introduction entirely and the
        wrong provisional guess would survive forever.

        #235: this used to have a sibling
        (test_without_provisional_idents_the_resumed_case_still_reconciles)
        that ran the identical setup with an EMPTY provisional-ident
        snapshot, to prove the snapshot was not the gate. With the snapshot
        deleted outright the two are the same test, so only this one
        remains -- the outcome asserted below is now reachable by no other
        input than the DB's own answer."""
        import mcp_server, frontier_registry
        repo = self._repo(tmp_path)
        linearization = frontier_registry.build_linearization(str(repo))
        commit_metadata = mcp_server._git_commits(str(repo), watermark_hash=None)
        allocator = mcp_server._frontier_load(real_db, linearization, "2026-01-04T00:00:00Z")
        mcp_server._reverse_fill_claim_and_process(
            real_db, str(repo), linearization, commit_metadata, allocator,
        )
        fn_ident = mcp_server._code_ident("function", "auth.py", "login")

        # Simulate the resumed-run preload: entity_valid_from ALREADY knows
        # this entity, because Stream 2 wrote its structural facts last run.
        state = mcp_server._ForwardWalkState(
            entity_valid_from={fn_ident: "2026-06-01T00:00:00Z"},
            entity_descriptions={fn_ident: "login"}, file_entities={"auth.py": [fn_ident]},
            file_deps={}, dep_valid_from={}, pinned_commit_state={},
            field_class_ident={}, field_static_ident={}, submodule_paths={},
            unresolved_dep_idents={},
            ts_by_commit_ident={f":commit/{h[:12]}": ts for h, ts, _a, _s in commit_metadata},
        )
        extracted = mcp_server._extract_commit(str(repo), linearization[0], ())
        mcp_server._forward_apply(
            real_db, str(repo), state, commit_metadata[0], extracted,
        )

        raw = mcp_server._db_execute(
            real_db, f"(query [:find ?c :where [{fn_ident} :introduced-by ?c]])",
        )
        assert {row[0] for row in json.loads(raw)["results"]} == {f":commit/{linearization[0][:12]}"}
        assert mcp_server._lineage_is_provisional(real_db, fn_ident) is False


class TestCloseRetractsIntroducedBy:
    """#231: every close site must retract :introduced-by, including for
    entities the reverse walk introduced (which the forward state never saw).
    """

    def test_resolve_prefers_the_walk_state(self, real_db):
        import mcp_server
        state = mcp_server._ForwardWalkState(
            entity_valid_from={}, entity_descriptions={}, file_entities={},
            file_deps={}, dep_valid_from={}, pinned_commit_state={},
            field_class_ident={}, field_static_ident={}, submodule_paths={},
            unresolved_dep_idents={},
        )
        state.entity_introduced_by[":function/a-py-f"] = ":commit/aaaaaaaaaaaa"
        real_db.execute('(transact [[:function/a-py-f :introduced-by :commit/zzzzzzzzzzzz]])')
        assert mcp_server._resolve_introduced_by(
            real_db, state, ":function/a-py-f") == ":commit/aaaaaaaaaaaa"

    def test_resolve_falls_back_to_the_db_for_reverse_introduced_entities(self, real_db):
        """Stage B closes entities Stream 2 introduced this run. They were never
        written through the forward state, so without this fallback #231 would
        survive for exactly those."""
        import mcp_server
        state = mcp_server._ForwardWalkState(
            entity_valid_from={}, entity_descriptions={}, file_entities={},
            file_deps={}, dep_valid_from={}, pinned_commit_state={},
            field_class_ident={}, field_static_ident={}, submodule_paths={},
            unresolved_dep_idents={},
        )
        real_db.execute('(transact [[:function/a-py-f :introduced-by :commit/zzzzzzzzzzzz]])')
        assert mcp_server._resolve_introduced_by(
            real_db, state, ":function/a-py-f") == ":commit/zzzzzzzzzzzz"

    def test_resolve_returns_none_for_an_entity_with_no_lineage(self, real_db):
        """Unresolved-import stubs never get :introduced-by."""
        import mcp_server
        state = mcp_server._ForwardWalkState(
            entity_valid_from={}, entity_descriptions={}, file_entities={},
            file_deps={}, dep_valid_from={}, pinned_commit_state={},
            field_class_ident={}, field_static_ident={}, submodule_paths={},
            unresolved_dep_idents={},
        )
        assert mcp_server._resolve_introduced_by(real_db, state, ":module/pkg-missing") is None


class TestRoundRobinClaimer:
    def _claimer(self, total, forward, reverse):
        import mcp_server, frontier_registry
        allocator = frontier_registry.FrontierAllocator(total, [])
        return mcp_server._RoundRobinClaimer(allocator, forward, reverse), allocator

    def _drain(self, claimer):
        out = []
        while True:
            claim = claimer.next_claim()
            if claim is None:
                return out
            out.append(claim)

    def test_one_to_one_alternates(self):
        claimer, _ = self._claimer(6, 1, 1)
        assert self._drain(claimer) == [
            ("fwd", 0), ("rev", 5), ("fwd", 1), ("rev", 4), ("fwd", 2), ("rev", 3),
        ]

    def test_one_to_three(self):
        claimer, _ = self._claimer(8, 1, 3)
        assert self._drain(claimer) == [
            ("fwd", 0), ("rev", 7), ("rev", 6), ("rev", 5),
            ("fwd", 1), ("rev", 4), ("rev", 3), ("rev", 2),
        ]

    def test_three_to_one(self):
        claimer, _ = self._claimer(8, 3, 1)
        assert self._drain(claimer) == [
            ("fwd", 0), ("fwd", 1), ("fwd", 2), ("rev", 7),
            ("fwd", 3), ("fwd", 4), ("fwd", 5), ("rev", 6),
        ]

    def test_every_position_claimed_exactly_once(self):
        for total in (1, 2, 3, 7, 20, 33):
            for ratio in ((1, 1), (1, 3), (3, 1), (2, 5)):
                claimer, _ = self._claimer(total, *ratio)
                claims = self._drain(claimer)
                positions = [pos for _tag, pos in claims]
                assert sorted(positions) == list(range(total)), (total, ratio)

    def test_forward_ascending_reverse_descending(self):
        claimer, _ = self._claimer(20, 2, 3)
        claims = self._drain(claimer)
        fwd = [pos for tag, pos in claims if tag == "fwd"]
        rev = [pos for tag, pos in claims if tag == "rev"]
        assert fwd == sorted(fwd), "forward state machine requires ascending"
        assert rev == sorted(rev, reverse=True), "2b's monotonicity guard requires descending"

    def test_empty_linearization_yields_nothing(self):
        claimer, _ = self._claimer(0, 1, 1)
        assert claimer.next_claim() is None

    def test_single_position_goes_to_whoever_asks_first(self):
        claimer, _ = self._claimer(1, 1, 1)
        assert claimer.next_claim() == ("fwd", 0)
        assert claimer.next_claim() is None

    def test_pre_drained_gap_yields_nothing_immediately(self):
        """Resume case: the previous run already covered everything."""
        claimer, allocator = self._claimer(5, 1, 1)
        while allocator.claim_low() is not None:
            pass
        assert claimer.next_claim() is None

    def test_starved_forward_resets_the_phase_counter_before_reverse_claims(self):
        """#325 review round 3, Finding 5: a starved forward turn used to
        leave `_taken_in_phase` accumulated under forward's own budget while
        immediately checking it against reverse's limit for the SAME call --
        detaching the phase counter from either budget's actual meaning the
        moment forward could not contribute, and silently unmooring
        MINIGRAF_INGEST_STREAM_RATIO from what it configures.

        Not independently observable via next_claim()'s own return sequence
        here: claim_high() always returns whatever position the allocator's
        own gap state dictates, regardless of which budget the internal
        counter mis-tracks against, so a permanently-starved forward stream
        (the only reachable case today -- Ruling 1 of round 2 starves it
        for the rest of the run once triggered) still hands out the same
        positions in the same order either way. This asserts the INTERNAL
        bookkeeping directly instead, which is where the bug actually lives
        and where a future caller (e.g. one that inspects the phase state,
        or a fold mechanism that could someday un-starve forward mid-run)
        would be misled.

        Ablation-proven: reverted to the pre-fix code, forward accumulates
        2 real claims (`_taken_in_phase == 2`) before starving; the third
        call (the first real reverse claim) left `_taken_in_phase == 3`
        (2 inherited + 1) and `_forward_phase` still True -- confirmed
        empirically before writing this assertion, not assumed.
        """
        import mcp_server, frontier_registry
        allocator = frontier_registry.FrontierAllocator(20, [
            frontier_registry.Interval(0, 0, frontier_registry.TAG_AUTHORITATIVE,
                                       anchor_pos=0, is_base=True),
            frontier_registry.Interval(3, 10, frontier_registry.TAG_PROVISIONAL,
                                       anchor_pos=10, is_base=True),
        ])
        claimer = mcp_server._RoundRobinClaimer(
            allocator, forward_per_round=5, reverse_per_round=5
        )
        assert claimer.next_claim() == ("fwd", 1)
        assert claimer.next_claim() == ("fwd", 2)
        # Position 3 is retained (part of the provisional interval), so the
        # next low position is 11 -- not adjacent to authoritative's edge
        # (0+1=1... now 2+1=3, and 11 != 3) -- claim_low() refuses, and this
        # falls through to the first real reverse claim.
        assert claimer.next_claim() == ("rev", 19)
        assert claimer._taken_in_phase == 1, (
            "the fallback reverse claim must start reverse's own budget "
            "count at 1 (itself), not inherit forward's accumulated count"
        )
        assert claimer._forward_phase is False, (
            "the phase flag must already read reverse -- it must not stay "
            "mislabeled forward until a stale inherited counter happens to "
            "trip reverse's limit on some later call"
        )


class TestStageAInterleave:
    """#222 phase 2d Task 8: _run_ingestion driven by the shared-gap claimer.

    Real on-disk graph throughout (docs/testing-conventions.md Pattern 2):
    _run_ingestion releases and reopens the DB between every commit, which an
    in-memory store cannot survive.
    """

    def _repo(self, tmp_path, n_commits=6):
        repo = tmp_path / "repo"
        repo.mkdir()
        # -b master explicitly: init.defaultBranch is machine-configurable, and
        # every test below passes "master" to _run_ingestion.
        _subprocess.run(["git", "init", "-b", "master"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.email", "t@t.com"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.name", "T"], cwd=repo, check=True, capture_output=True)
        for i in range(n_commits):
            (repo / "auth.py").write_text(f"def login():\n    return {i}\n")
            _subprocess.run(["git", "add", "."], cwd=repo, check=True, capture_output=True)
            _subprocess.run(["git", "commit", "-m", f"h{i}"], cwd=repo, check=True, capture_output=True)
        return repo

    @pytest.mark.asyncio
    async def test_both_frontiers_advance_and_meet(self, tmp_path, monkeypatch):
        """The load-bearing property: a real run must leave frontier-low and
        frontier-high adjacent, covering every position exactly once."""
        import mcp_server, frontier_registry
        from minigraf import MiniGrafDb
        repo = self._repo(tmp_path)
        graph = tmp_path / "g.graph"
        mcp_server.open_db(str(graph))
        monkeypatch.setenv("MINIGRAF_INGEST_STREAM_RATIO", "1:1")

        await mcp_server._run_ingestion(str(repo), "master")
        mcp_server._reset_db_state()

        db = MiniGrafDb.open(str(graph))
        linearization = frontier_registry.build_linearization(str(repo))
        low = mcp_server._frontier_read_bounds(db, mcp_server._FRONTIER_LOW_IDENT)
        high = mcp_server._frontier_read_bounds(db, mcp_server._FRONTIER_HIGH_IDENT)
        assert low is not None and high is not None, "both streams must have claimed"
        pos = {h: i for i, h in enumerate(linearization)}
        assert pos[low[0]] == 0
        assert pos[high[1]] == len(linearization) - 1
        assert pos[low[1]] + 1 == pos[high[0]], "the two frontiers must be adjacent"

    @pytest.mark.asyncio
    async def test_forward_heavy_ratio_shifts_the_meeting_point(self, tmp_path, monkeypatch):
        import mcp_server, frontier_registry
        from minigraf import MiniGrafDb
        repo = self._repo(tmp_path, n_commits=8)
        graph = tmp_path / "g.graph"
        mcp_server.open_db(str(graph))
        monkeypatch.setenv("MINIGRAF_INGEST_STREAM_RATIO", "3:1")

        await mcp_server._run_ingestion(str(repo), "master")
        mcp_server._reset_db_state()

        db = MiniGrafDb.open(str(graph))
        linearization = frontier_registry.build_linearization(str(repo))
        pos = {h: i for i, h in enumerate(linearization)}
        low = mcp_server._frontier_read_bounds(db, mcp_server._FRONTIER_LOW_IDENT)
        # 3:1 over 8 positions -> forward takes 6, reverse takes 2.
        assert pos[low[1]] == 5

    @pytest.mark.asyncio
    async def test_watermark_matches_frontier_low_hi(self, tmp_path, monkeypatch):
        """:ingestion/watermark keeps its contiguous-from-C0 meaning: it is
        advanced by the forward stream only, never by the reverse one."""
        import mcp_server
        from minigraf import MiniGrafDb
        repo = self._repo(tmp_path)
        graph = tmp_path / "g.graph"
        mcp_server.open_db(str(graph))
        await mcp_server._run_ingestion(str(repo), "master")
        mcp_server._reset_db_state()

        db = MiniGrafDb.open(str(graph))
        low = mcp_server._frontier_read_bounds(db, mcp_server._FRONTIER_LOW_IDENT)
        assert mcp_server._watermark_query(db) == low[1]

    @pytest.mark.asyncio
    async def test_single_commit_repo(self, tmp_path, monkeypatch):
        import mcp_server
        repo = self._repo(tmp_path, n_commits=1)
        mcp_server.open_db(str(tmp_path / "g.graph"))
        await mcp_server._run_ingestion(str(repo), "master")
        assert mcp_server._ingest_progress["status"] == "complete"

    @pytest.mark.asyncio
    async def test_second_run_on_unchanged_repo_is_a_no_op(self, tmp_path, monkeypatch):
        """Resume with an already-empty gap: Stage A must never begin, not
        spin or re-process."""
        import mcp_server
        repo = self._repo(tmp_path)
        mcp_server.open_db(str(tmp_path / "g.graph"))
        await mcp_server._run_ingestion(str(repo), "master")
        mcp_server._reset_db_state()
        mcp_server.open_db(str(tmp_path / "g.graph"))
        await mcp_server._run_ingestion(str(repo), "master")
        assert mcp_server._ingest_progress["status"] == "complete"


class TestStageBCorrectionSweep:
    """#222 phase 2d Task 9: Stage B -- the sequential correction sweep that
    runs once Stage A's two streams have drained and the shared gap is
    closed, turning the reverse stream's provisional guesses authoritative.

    Real on-disk graph throughout (docs/testing-conventions.md Pattern 2):
    _run_ingestion releases and reopens the DB between every commit, which an
    in-memory store cannot survive.
    """

    def _repo(self, tmp_path, n_commits=6):
        repo = tmp_path / "repo"
        repo.mkdir()
        # -b master explicitly: init.defaultBranch is machine-configurable, and
        # every test below passes "master" to _run_ingestion.
        _subprocess.run(["git", "init", "-b", "master"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.email", "t@t.com"], cwd=repo, check=True, capture_output=True)
        _subprocess.run(["git", "config", "user.name", "T"], cwd=repo, check=True, capture_output=True)
        for i in range(n_commits):
            (repo / "auth.py").write_text(
                f"def login():\n    return {i}\n\ndef helper_{i}():\n    pass\n"
            )
            _subprocess.run(["git", "add", "."], cwd=repo, check=True, capture_output=True)
            _subprocess.run(["git", "commit", "-m", f"h{i}"], cwd=repo, check=True, capture_output=True)
        return repo

    @pytest.mark.asyncio
    async def test_completed_run_leaves_no_provisional_markers(self, tmp_path, monkeypatch):
        """The headline postcondition of phase 2: after a full ingest,
        every entity's lineage is authoritative."""
        import mcp_server
        from minigraf import MiniGrafDb
        repo = self._repo(tmp_path)
        graph = tmp_path / "g.graph"
        mcp_server.open_db(str(graph))
        await mcp_server._run_ingestion(str(repo), "master")
        mcp_server._reset_db_state()

        db = MiniGrafDb.open(str(graph))
        assert mcp_server._preload_provisional_idents(db) == set()

    @pytest.mark.asyncio
    async def test_no_entity_has_two_introduced_by_values(self, tmp_path, monkeypatch):
        import mcp_server
        from minigraf import MiniGrafDb
        repo = self._repo(tmp_path)
        graph = tmp_path / "g.graph"
        mcp_server.open_db(str(graph))
        await mcp_server._run_ingestion(str(repo), "master")
        mcp_server._reset_db_state()

        db = MiniGrafDb.open(str(graph))
        raw = mcp_server._db_execute(db, "(query [:find ?e ?c :where [?e :introduced-by ?c]])")
        pairs = [tuple(row) for row in json.loads(raw)["results"]]
        entities = [e for e, _c in pairs]
        assert len(entities) == len(set(entities)), f"duplicate :introduced-by: {pairs}"

    @pytest.mark.asyncio
    async def test_lineage_confirmed_through_reaches_head(self, tmp_path, monkeypatch):
        import mcp_server
        from minigraf import MiniGrafDb
        repo = self._repo(tmp_path)
